{"file_path": "scripts/update-flow-models.ts", "initial_content": "#!/usr/bin/env ts-node
/**
 * Script to update model references in AI flows
 * 
 * This script updates all flows to use the appropriate Ollama models
 * based on the task category mapping defined in src/ai/model-mapping.ts
 */

import * as fs from 'fs';
import * as path from 'path';

const FLOW_MODEL_UPDATES = {
  // 🔄 Conversion & Processing - Gemma 2B
  'rewrite-to-markdown.ts': 'ollama/gemma:2b',
  'rewrite-document-to-markdown.ts': 'ollama/gemma:2b',
  'translate-text.ts': 'ollama/gemma:2b',
  'summarize-document.ts': 'ollama/gemma:2b',
  'summarize-text.ts': 'ollama/gemma:2b',
  'image-to-text.ts': 'ollama/gemma:2b',

  // ✍️ Text Generation & Writing - Gemma 2B
  'generate-text.ts': 'ollama/gemma:2b',
  'paraphrase-text.ts': 'ollama/gemma:2b',
  'humanize-text.ts': 'ollama/gemma:2b',
  'manipulate-text.ts': 'ollama/gemma:2b',
  'text-stylist.ts': 'ollama/gemma:2b',
  'write-document.ts': 'ollama/gemma:2b',
  'ai-proofread-document.ts': 'ollama/gemma:2b',
  'generate-ideas.ts': 'ollama/gemma:2b',
  'topic-explainer.ts': 'ollama/gemma:2b',

  // 📊 Reports & Documentation - Phi-3 Mini
  'improve-report-markdown.ts': 'ollama/phi3:mini',
  'generate-toc.ts': 'ollama/phi3:mini',
  'generate-chapter-content.ts': 'ollama/phi3:mini',
  'generate-chapter-content-rag.ts': 'ollama/phi3:mini',
  'generate-report-section.ts': 'ollama/phi3:mini',
  'generate-report-section-rag.ts': 'ollama/phi3:mini',
  'project-documentation-generator.ts': 'ollama/phi3:mini',
  'professional-document-writer.ts': 'ollama/phi3:mini',
  'technical-spec-writer.ts': 'ollama/phi3:mini',
  'generate-session-plan.ts': 'ollama/phi3:mini',
  'create-lecture-unit.ts': 'ollama/phi3:mini',
  'generate-theoretical-lecture.ts': 'ollama/phi3:mini',
  'presentation-content-creator.ts': 'ollama/phi3:mini',

  // ✅ Checking & Analysis - Phi-3 Mini
  'grammar-checker.ts': 'ollama/phi3:mini',
  'sentence-structure-checker.ts': 'ollama/phi3:mini',
  'bias-checker.ts': 'ollama/phi3:mini',
  'fact-checker.ts': 'ollama/phi3:mini',
  'detect-ai-content.ts': 'ollama/phi3:mini',
  'plagiarism-checker.ts': 'ollama/phi3:mini',
  'academic-paper-quality-checker.ts': 'ollama/phi3:mini',
  'analyze-context.ts': 'ollama/phi3:mini',

  // 🎯 Specific Structured Tasks - Phi-3 Mini
  'generate-citation.ts': 'ollama/phi3:mini',
  'generate-plantuml.ts': 'ollama/phi3:mini',
  'generate-ui-description.ts': 'ollama/phi3:mini',
  'generate-quiz.ts': 'ollama/phi3:mini',
  'generate-project-blueprint.ts': 'ollama/phi3:mini',
  'generate-agent-config.ts': 'ollama/phi3:mini',
  'question-answering.ts': 'ollama/phi3:mini',

  // 🎓 Academic & Research - Llama 3 8B
  'academic-literature-review.ts': 'ollama/llama3:8b',
  'ai-researcher.ts': 'ollama/llama3:8b',
  'literature-review-generator.ts': 'ollama/llama3:8b',
  'graduation-project-generator.ts': 'ollama/llama3:8b',
  'project-report-generator.ts': 'ollama/llama3:8b',
  'fact-retrieval.ts': 'ollama/llama3:8b',
  'solve-assignments.ts': 'ollama/llama3:8b',
  'run-agent-flow.ts': 'ollama/llama3:8b',
};

const flowsDir = path.join(__dirname, '../src/ai/flows');

function updateFlowModel(filePath: string, newModel: string) {
  let content = fs.readFileSync(filePath, 'utf-8');
  let updated = false;

  // Pattern 1: model: 'ollama/gemma:2b'
  const pattern1 = /model:\s*['"]ollama\/[^'"]+['"]/g;
  if (pattern1.test(content)) {
    content = content.replace(pattern1, `model: '${newModel}'`);
    updated = true;
  }

  if (updated) {
    fs.writeFileSync(filePath, content, 'utf-8');
    return true;
  }

  return false;
}

function main() {
  console.log('🚀 Updating AI flow models...\n');

  let updatedCount = 0;
  let skippedCount = 0;

  for (const [fileName, newModel] of Object.entries(FLOW_MODEL_UPDATES)) {
    const filePath = path.join(flowsDir, fileName);

    if (!fs.existsSync(filePath)) {
      console.log(`⚠️  File not found: ${fileName}`);
      skippedCount++;
      continue;
    }

    try {
      const wasUpdated = updateFlowModel(filePath, newModel);
      if (wasUpdated) {
        console.log(`✅ Updated ${fileName} → ${newModel}`);
        updatedCount++;
      } else {
        console.log(`⏭️  Skipped ${fileName} (no model found)`);
        skippedCount++;
      }
    } catch (error) {
      console.error(`❌ Error updating ${fileName}:`, error);
      skippedCount++;
    }
  }

  console.log(`\n📊 Summary:`);
  console.log(`   ✅ Updated: ${updatedCount} files`);
  console.log(`   ⏭️  Skipped: ${skippedCount} files`);
  console.log(`\n✨ Done!`);
}

main();
"}

