{"file_path": "src/ai/model-selector.ts", "initial_content": "/**
 * Model Selection Utilities
 * 
 * Provides intelligent model selection based on various factors:
 * - Task type and complexity
 * - Content length and context size
 * - Performance requirements
 * - Resource availability
 */

import { OLLAMA_MODELS, MODEL_BY_TASK } from './genkit';
import { FLOW_MODEL_MAPPING } from './model-mapping';

/**
 * Task complexity levels
 */
export enum TaskComplexity {
  SIMPLE = 'simple',       // Basic text operations
  MODERATE = 'moderate',   // Analysis, structured output
  COMPLEX = 'complex',     // Academic, research, reasoning
}

/**
 * Performance priority settings
 */
export enum PerformancePriority {
  SPEED = 'speed',         // Prioritize fast response
  BALANCED = 'balanced',   // Balance speed and quality
  QUALITY = 'quality',     // Prioritize output quality
}

/**
 * Model selection criteria
 */
export interface ModelSelectionCriteria {
  flowName?: string;
  taskComplexity?: TaskComplexity;
  performancePriority?: PerformancePriority;
  inputTokens?: number;
  requiresStructuredOutput?: boolean;
  requiresDeepReasoning?: boolean;
  isAcademic?: boolean;
  hasRAGContext?: boolean;
}

/**
 * Model characteristics for selection logic
 */
interface ModelCharacteristics {
  speed: number;           // 1-10 (higher is faster)
  quality: number;         // 1-10 (higher is better)
  reasoning: number;       // 1-10 (higher is better)
  structuredOutput: number; // 1-10 (higher is better)
  memoryUsage: number;     // GB
  maxConcurrent: number;   // Recommended concurrent requests
}

const MODEL_CHARACTERISTICS: Record<string, ModelCharacteristics> = {
  [OLLAMA_MODELS.GEMMA_2B]: {
    speed: 9,
    quality: 6,
    reasoning: 5,
    structuredOutput: 6,
    memoryUsage: 2.5,
    maxConcurrent: 5,
  },
  [OLLAMA_MODELS.PHI3_MINI]: {
    speed: 7,
    quality: 8,
    reasoning: 8,
    structuredOutput: 9,
    memoryUsage: 3.3,
    maxConcurrent: 3,
  },
  [OLLAMA_MODELS.LLAMA3_8B]: {
    speed: 4,
    quality: 10,
    reasoning: 10,
    structuredOutput: 8,
    memoryUsage: 4.7,
    maxConcurrent: 1,
  },
};

/**
 * Get recommended model for a specific flow
 */
export function getModelForFlow(flowName: string): string {
  return FLOW_MODEL_MAPPING[flowName as keyof typeof FLOW_MODEL_MAPPING] || MODEL_BY_TASK.TEXT_GENERATION;
}

/**
 * Select model based on task complexity
 */
export function selectModelByComplexity(complexity: TaskComplexity): string {
  switch (complexity) {
    case TaskComplexity.SIMPLE:
      return OLLAMA_MODELS.GEMMA_2B;
    case TaskComplexity.MODERATE:
      return OLLAMA_MODELS.PHI3_MINI;
    case TaskComplexity.COMPLEX:
      return OLLAMA_MODELS.LLAMA3_8B;
    default:
      return OLLAMA_MODELS.GEMMA_2B;
  }
}

/**
 * Select model based on performance priority
 */
export function selectModelByPriority(priority: PerformancePriority): string {
  switch (priority) {
    case PerformancePriority.SPEED:
      return OLLAMA_MODELS.GEMMA_2B;
    case PerformancePriority.BALANCED:
      return OLLAMA_MODELS.PHI3_MINI;
    case PerformancePriority.QUALITY:
      return OLLAMA_MODELS.LLAMA3_8B;
    default:
      return OLLAMA_MODELS.PHI3_MINI;
  }
}

/**
 * Select model based on input token count
 */
export function selectModelByTokenCount(tokens: number): string {
  // For very large inputs, use models with better context handling
  if (tokens > 4000) {
    return OLLAMA_MODELS.LLAMA3_8B;
  } else if (tokens > 2000) {
    return OLLAMA_MODELS.PHI3_MINI;
  }
  return OLLAMA_MODELS.GEMMA_2B;
}

/**
 * Intelligent model selection based on multiple criteria
 */
export function selectModel(criteria: ModelSelectionCriteria): string {
  // Priority 1: If flow name is specified, use predefined mapping
  if (criteria.flowName) {
    const flowModel = getModelForFlow(criteria.flowName);
    if (flowModel) return flowModel;
  }

  // Priority 2: Academic tasks always use Llama 3 8B
  if (criteria.isAcademic) {
    return OLLAMA_MODELS.LLAMA3_8B;
  }

  // Priority 3: Deep reasoning tasks
  if (criteria.requiresDeepReasoning) {
    return criteria.hasRAGContext ? OLLAMA_MODELS.LLAMA3_8B : OLLAMA_MODELS.PHI3_MINI;
  }

  // Priority 4: Structured output needs
  if (criteria.requiresStructuredOutput) {
    return OLLAMA_MODELS.PHI3_MINI;
  }

  // Priority 5: Performance priority
  if (criteria.performancePriority) {
    return selectModelByPriority(criteria.performancePriority);
  }

  // Priority 6: Task complexity
  if (criteria.taskComplexity) {
    return selectModelByComplexity(criteria.taskComplexity);
  }

  // Priority 7: Input token count
  if (criteria.inputTokens) {
    return selectModelByTokenCount(criteria.inputTokens);
  }

  // Default: Use Phi-3 Mini for balanced performance
  return OLLAMA_MODELS.PHI3_MINI;
}

/**
 * Get model characteristics
 */
export function getModelCharacteristics(model: string): ModelCharacteristics | null {
  return MODEL_CHARACTERISTICS[model] || null;
}

/**
 * Compare two models and return the better one based on criteria
 */
export function compareModels(
  model1: string,
  model2: string,
  priority: 'speed' | 'quality' | 'reasoning' | 'structuredOutput'
): string {
  const char1 = MODEL_CHARACTERISTICS[model1];
  const char2 = MODEL_CHARACTERISTICS[model2];

  if (!char1 || !char2) {
    return model1;
  }

  return char1[priority] >= char2[priority] ? model1 : model2;
}

/**
 * Check if model is available for concurrent requests
 */
export function canHandleConcurrentRequest(model: string, currentRequests: number): boolean {
  const characteristics = MODEL_CHARACTERISTICS[model];
  if (!characteristics) return false;
  return currentRequests < characteristics.maxConcurrent;
}

/**
 * Get recommended concurrent request limit for a model
 */
export function getMaxConcurrentRequests(model: string): number {
  const characteristics = MODEL_CHARACTERISTICS[model];
  return characteristics?.maxConcurrent || 1;
}

/**
 * Estimate memory usage for a model
 */
export function estimateMemoryUsage(model: string): number {
  const characteristics = MODEL_CHARACTERISTICS[model];
  return characteristics?.memoryUsage || 0;
}

/**
 * Get all available models sorted by a characteristic
 */
export function getModelsSortedBy(
  characteristic: 'speed' | 'quality' | 'reasoning' | 'structuredOutput'
): string[] {
  return Object.entries(MODEL_CHARACTERISTICS)
    .sort((a, b) => b[1][characteristic] - a[1][characteristic])
    .map(([model]) => model);
}

/**
 * Check if model is suitable for task
 */
export function isModelSuitableForTask(model: string, criteria: ModelSelectionCriteria): boolean {
  const characteristics = MODEL_CHARACTERISTICS[model];
  if (!characteristics) return false;

  // Check academic requirement
  if (criteria.isAcademic && model !== OLLAMA_MODELS.LLAMA3_8B) {
    return false;
  }

  // Check structured output requirement
  if (criteria.requiresStructuredOutput && characteristics.structuredOutput < 8) {
    return false;
  }

  // Check deep reasoning requirement
  if (criteria.requiresDeepReasoning && characteristics.reasoning < 8) {
    return false;
  }

  return true;
}

/**
 * Get fallback model if primary is unavailable
 */
export function getFallbackModel(primaryModel: string): string {
  // If Llama 3 8B fails, fall back to Phi-3 Mini
  if (primaryModel === OLLAMA_MODELS.LLAMA3_8B) {
    return OLLAMA_MODELS.PHI3_MINI;
  }

  // If Phi-3 Mini fails, fall back to Gemma 2B
  if (primaryModel === OLLAMA_MODELS.PHI3_MINI) {
    return OLLAMA_MODELS.GEMMA_2B;
  }

  // Gemma 2B is the ultimate fallback
  return OLLAMA_MODELS.GEMMA_2B;
}

/**
 * Model selection result with metadata
 */
export interface ModelSelectionResult {
  model: string;
  reason: string;
  characteristics: ModelCharacteristics | null;
  fallbackModel: string;
  warnings: string[];
}

/**
 * Select model with detailed result information
 */
export function selectModelWithMetadata(criteria: ModelSelectionCriteria): ModelSelectionResult {
  const warnings: string[] = [];
  let reason = 'Default balanced selection';

  // Determine model
  let model: string;

  if (criteria.flowName) {
    model = getModelForFlow(criteria.flowName);
    reason = `Predefined mapping for flow: ${criteria.flowName}`;
  } else if (criteria.isAcademic) {
    model = OLLAMA_MODELS.LLAMA3_8B;
    reason = 'Academic task requires highest quality model';
    if (!criteria.hasRAGContext) {
      warnings.push('Academic tasks should use RAG context for best results');
    }
  } else if (criteria.requiresDeepReasoning) {
    model = criteria.hasRAGContext ? OLLAMA_MODELS.LLAMA3_8B : OLLAMA_MODELS.PHI3_MINI;
    reason = 'Deep reasoning task';
  } else if (criteria.requiresStructuredOutput) {
    model = OLLAMA_MODELS.PHI3_MINI;
    reason = 'Structured output requires Phi-3 Mini';
  } else if (criteria.performancePriority) {
    model = selectModelByPriority(criteria.performancePriority);
    reason = `Performance priority: ${criteria.performancePriority}`;
  } else if (criteria.taskComplexity) {
    model = selectModelByComplexity(criteria.taskComplexity);
    reason = `Task complexity: ${criteria.taskComplexity}`;
  } else if (criteria.inputTokens) {
    model = selectModelByTokenCount(criteria.inputTokens);
    reason = `Based on input token count: ${criteria.inputTokens}`;
  } else {
    model = OLLAMA_MODELS.PHI3_MINI;
  }

  // Add warnings for resource-intensive models
  const characteristics = MODEL_CHARACTERISTICS[model];
  if (model === OLLAMA_MODELS.LLAMA3_8B) {
    warnings.push('Llama 3 8B uses significant RAM (~4.7GB). Run one request at a time.');
    warnings.push('Consider using request queuing for multiple Llama 3 8B requests.');
  }

  if (criteria.inputTokens && criteria.inputTokens > 2000) {
    warnings.push('Large input detected. Monitor memory usage carefully.');
  }

  return {
    model,
    reason,
    characteristics,
    fallbackModel: getFallbackModel(model),
    warnings,
  };
}

/**
 * Export all model constants for convenience
 */
export { OLLAMA_MODELS, MODEL_BY_TASK };
"}

{"file_path": "src/ai/model-performance-monitor.ts", "initial_content": "/**
 * Model Performance Monitoring
 * 
 * Tracks and monitors model performance, resource usage, and request patterns.
 * Provides insights for optimization and model selection tuning.
 */

import { OLLAMA_MODELS } from './genkit';

/**
 * Performance metrics for a single request
 */
export interface RequestMetrics {
  model: string;
  flowName?: string;
  startTime: number;
  endTime?: number;
  duration?: number;
  inputTokens?: number;
  outputTokens?: number;
  success: boolean;
  error?: string;
  memoryUsageMB?: number;
}

/**
 * Aggregated performance statistics
 */
export interface ModelStatistics {
  model: string;
  totalRequests: number;
  successfulRequests: number;
  failedRequests: number;
  averageDuration: number;
  minDuration: number;
  maxDuration: number;
  totalTokensProcessed: number;
  averageInputTokens: number;
  averageOutputTokens: number;
  averageMemoryUsageMB: number;
  lastUsed: number;
  errorRate: number;
}

/**
 * Performance monitor class
 */
class ModelPerformanceMonitor {
  private metrics: RequestMetrics[] = [];
  private activeRequests: Map<string, RequestMetrics> = new Map();
  private maxMetricsHistory = 1000; // Keep last 1000 requests
  private requestCounts: Map<string, number> = new Map();

  /**
   * Start tracking a request
   */
  startRequest(requestId: string, model: string, flowName?: string): void {
    const metric: RequestMetrics = {
      model,
      flowName,
      startTime: Date.now(),
      success: false,
    };
    this.activeRequests.set(requestId, metric);
  }

  /**
   * End tracking a request
   */
  endRequest(
    requestId: string,
    success: boolean,
    error?: string,
    inputTokens?: number,
    outputTokens?: number,
    memoryUsageMB?: number
  ): void {
    const metric = this.activeRequests.get(requestId);
    if (!metric) return;

    metric.endTime = Date.now();
    metric.duration = metric.endTime - metric.startTime;
    metric.success = success;
    metric.error = error;
    metric.inputTokens = inputTokens;
    metric.outputTokens = outputTokens;
    metric.memoryUsageMB = memoryUsageMB;

    this.metrics.push(metric);
    this.activeRequests.delete(requestId);

    // Maintain max history size
    if (this.metrics.length > this.maxMetricsHistory) {
      this.metrics.shift();
    }

    // Update request count
    const currentCount = this.requestCounts.get(metric.model) || 0;
    this.requestCounts.set(metric.model, currentCount + 1);
  }

  /**
   * Get statistics for a specific model
   */
  getModelStatistics(model: string): ModelStatistics {
    const modelMetrics = this.metrics.filter((m) => m.model === model && m.duration);

    if (modelMetrics.length === 0) {
      return {
        model,
        totalRequests: 0,
        successfulRequests: 0,
        failedRequests: 0,
        averageDuration: 0,
        minDuration: 0,
        maxDuration: 0,
        totalTokensProcessed: 0,
        averageInputTokens: 0,
        averageOutputTokens: 0,
        averageMemoryUsageMB: 0,
        lastUsed: 0,
        errorRate: 0,
      };
    }

    const successfulRequests = modelMetrics.filter((m) => m.success).length;
    const failedRequests = modelMetrics.length - successfulRequests;
    const durations = modelMetrics.map((m) => m.duration || 0);
    const inputTokens = modelMetrics.map((m) => m.inputTokens || 0);
    const outputTokens = modelMetrics.map((m) => m.outputTokens || 0);
    const memoryUsages = modelMetrics.filter((m) => m.memoryUsageMB).map((m) => m.memoryUsageMB || 0);

    return {
      model,
      totalRequests: modelMetrics.length,
      successfulRequests,
      failedRequests,
      averageDuration: durations.reduce((a, b) => a + b, 0) / durations.length,
      minDuration: Math.min(...durations),
      maxDuration: Math.max(...durations),
      totalTokensProcessed: inputTokens.reduce((a, b) => a + b, 0) + outputTokens.reduce((a, b) => a + b, 0),
      averageInputTokens: inputTokens.reduce((a, b) => a + b, 0) / inputTokens.length,
      averageOutputTokens: outputTokens.reduce((a, b) => a + b, 0) / outputTokens.length,
      averageMemoryUsageMB: memoryUsages.length > 0 ? memoryUsages.reduce((a, b) => a + b, 0) / memoryUsages.length : 0,
      lastUsed: Math.max(...modelMetrics.map((m) => m.startTime)),
      errorRate: failedRequests / modelMetrics.length,
    };
  }

  /**
   * Get statistics for all models
   */
  getAllStatistics(): ModelStatistics[] {
    const models = [OLLAMA_MODELS.GEMMA_2B, OLLAMA_MODELS.PHI3_MINI, OLLAMA_MODELS.LLAMA3_8B];
    return models.map((model) => this.getModelStatistics(model));
  }

  /**
   * Get current active requests count per model
   */
  getActiveRequestCounts(): Record<string, number> {
    const counts: Record<string, number> = {};
    this.activeRequests.forEach((metric) => {
      counts[metric.model] = (counts[metric.model] || 0) + 1;
    });
    return counts;
  }

  /**
   * Check if model can handle more concurrent requests
   */
  canHandleRequest(model: string, maxConcurrent: number): boolean {
    const activeCounts = this.getActiveRequestCounts();
    const currentCount = activeCounts[model] || 0;
    return currentCount < maxConcurrent;
  }

  /**
   * Get recent errors for debugging
   */
  getRecentErrors(limit = 10): RequestMetrics[] {
    return this.metrics
      .filter((m) => !m.success && m.error)
      .slice(-limit)
      .reverse();
  }

  /**
   * Get slowest requests for optimization
   */
  getSlowestRequests(limit = 10): RequestMetrics[] {
    return [...this.metrics]
      .filter((m) => m.duration)
      .sort((a, b) => (b.duration || 0) - (a.duration || 0))
      .slice(0, limit);
  }

  /**
   * Get performance comparison between models
   */
  compareModels(): Record<string, { avgSpeed: number; avgQuality: number; reliability: number }> {
    const stats = this.getAllStatistics();
    const comparison: Record<string, { avgSpeed: number; avgQuality: number; reliability: number }> = {};

    stats.forEach((stat) => {
      // Speed: inverse of average duration (lower duration = higher speed score)
      const avgSpeed = stat.averageDuration > 0 ? 1000 / stat.averageDuration : 0;

      // Quality: proxy based on output tokens (more output typically = better quality)
      const avgQuality = stat.averageOutputTokens;

      // Reliability: 1 - error rate
      const reliability = 1 - stat.errorRate;

      comparison[stat.model] = {
        avgSpeed: Math.round(avgSpeed * 100) / 100,
        avgQuality: Math.round(avgQuality * 100) / 100,
        reliability: Math.round(reliability * 100) / 100,
      };
    });

    return comparison;
  }

  /**
   * Get performance report
   */
  generateReport(): string {
    const stats = this.getAllStatistics();
    const activeRequests = this.getActiveRequestCounts();

    let report = '📊 MODEL PERFORMANCE REPORT\n';
    report += '═══════════════════════════════════════\n\n';

    stats.forEach((stat) => {
      const modelName = stat.model.split('/')[1] || stat.model;
      report += `🤖 ${modelName.toUpperCase()}\n`;
      report += `   Total Requests: ${stat.totalRequests}\n`;
      report += `   Success Rate: ${((stat.successfulRequests / stat.totalRequests) * 100).toFixed(1)}%\n`;
      report += `   Avg Duration: ${stat.averageDuration.toFixed(0)}ms\n`;
      report += `   Range: ${stat.minDuration.toFixed(0)}ms - ${stat.maxDuration.toFixed(0)}ms\n`;
      report += `   Avg Input Tokens: ${stat.averageInputTokens.toFixed(0)}\n`;
      report += `   Avg Output Tokens: ${stat.averageOutputTokens.toFixed(0)}\n`;
      if (stat.averageMemoryUsageMB > 0) {
        report += `   Avg Memory: ${stat.averageMemoryUsageMB.toFixed(1)}MB\n`;
      }
      report += `   Active Requests: ${activeRequests[stat.model] || 0}\n`;
      report += '\n';
    });

    report += '📈 MODEL COMPARISON\n';
    report += '═══════════════════════════════════════\n';
    const comparison = this.compareModels();
    Object.entries(comparison).forEach(([model, metrics]) => {
      const modelName = model.split('/')[1] || model;
      report += `   ${modelName}: Speed=${metrics.avgSpeed.toFixed(2)} | Quality=${metrics.avgQuality.toFixed(0)} | Reliability=${(metrics.reliability * 100).toFixed(1)}%\n`;
    });

    return report;
  }

  /**
   * Reset all metrics
   */
  reset(): void {
    this.metrics = [];
    this.activeRequests.clear();
    this.requestCounts.clear();
  }

  /**
   * Export metrics as JSON
   */
  exportMetrics(): string {
    return JSON.stringify({
      metrics: this.metrics,
      statistics: this.getAllStatistics(),
      activeRequests: Object.fromEntries(this.activeRequests),
      timestamp: Date.now(),
    }, null, 2);
  }

  /**
   * Get metrics for specific flow
   */
  getFlowStatistics(flowName: string): {
    totalRequests: number;
    averageDuration: number;
    modelUsage: Record<string, number>;
  } {
    const flowMetrics = this.metrics.filter((m) => m.flowName === flowName && m.duration);

    if (flowMetrics.length === 0) {
      return {
        totalRequests: 0,
        averageDuration: 0,
        modelUsage: {},
      };
    }

    const modelUsage: Record<string, number> = {};
    flowMetrics.forEach((m) => {
      modelUsage[m.model] = (modelUsage[m.model] || 0) + 1;
    });

    return {
      totalRequests: flowMetrics.length,
      averageDuration: flowMetrics.reduce((sum, m) => sum + (m.duration || 0), 0) / flowMetrics.length,
      modelUsage,
    };
  }
}

// Singleton instance
export const performanceMonitor = new ModelPerformanceMonitor();

/**
 * Helper function to track a request
 */
export async function trackRequest<T>(
  requestId: string,
  model: string,
  flowName: string | undefined,
  operation: () => Promise<T>,
  getTokenCounts?: () => { input?: number; output?: number }
): Promise<T> {
  performanceMonitor.startRequest(requestId, model, flowName);

  try {
    const result = await operation();
    const tokens = getTokenCounts?.();
    performanceMonitor.endRequest(
      requestId,
      true,
      undefined,
      tokens?.input,
      tokens?.output
    );
    return result;
  } catch (error) {
    performanceMonitor.endRequest(
      requestId,
      false,
      error instanceof Error ? error.message : 'Unknown error'
    );
    throw error;
  }
}

/**
 * Generate a unique request ID
 */
export function generateRequestId(): string {
  return `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}
"}

{"file_path": "src/ai/model-request-queue.ts", "initial_content": "/**
 * Model Request Queue Manager
 * 
 * Manages request queuing and concurrency limits for different models.
 * Prevents memory overload by controlling concurrent requests per model.
 */

import { OLLAMA_MODELS } from './genkit';
import { getMaxConcurrentRequests } from './model-selector';
import { performanceMonitor } from './model-performance-monitor';

/**
 * Request priority levels
 */
export enum RequestPriority {
  LOW = 0,
  NORMAL = 1,
  HIGH = 2,
  URGENT = 3,
}

/**
 * Queued request information
 */
interface QueuedRequest<T> {
  id: string;
  model: string;
  flowName?: string;
  priority: RequestPriority;
  operation: () => Promise<T>;
  resolve: (value: T) => void;
  reject: (error: Error) => void;
  queuedAt: number;
  timeout?: number;
}

/**
 * Queue statistics
 */
export interface QueueStats {
  model: string;
  queuedRequests: number;
  activeRequests: number;
  maxConcurrent: number;
  averageWaitTime: number;
  totalProcessed: number;
}

/**
 * Request queue manager for a specific model
 */
class ModelQueue {
  private queue: QueuedRequest<any>[] = [];
  private activeRequests = 0;
  private maxConcurrent: number;
  private model: string;
  private totalProcessed = 0;
  private totalWaitTime = 0;

  constructor(model: string, maxConcurrent?: number) {
    this.model = model;
    this.maxConcurrent = maxConcurrent || getMaxConcurrentRequests(model);
  }

  /**
   * Add request to queue
   */
  async enqueue<T>(
    id: string,
    flowName: string | undefined,
    operation: () => Promise<T>,
    priority: RequestPriority = RequestPriority.NORMAL,
    timeout?: number
  ): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const request: QueuedRequest<T> = {
        id,
        model: this.model,
        flowName,
        priority,
        operation,
        resolve,
        reject,
        queuedAt: Date.now(),
        timeout,
      };

      // Insert based on priority
      const insertIndex = this.queue.findIndex((r) => r.priority < priority);
      if (insertIndex === -1) {
        this.queue.push(request);
      } else {
        this.queue.splice(insertIndex, 0, request);
      }

      // Try to process immediately
      this.processNext();
    });
  }

  /**
   * Process next request in queue
   */
  private async processNext(): Promise<void> {
    if (this.activeRequests >= this.maxConcurrent || this.queue.length === 0) {
      return;
    }

    const request = this.queue.shift();
    if (!request) return;

    this.activeRequests++;
    const waitTime = Date.now() - request.queuedAt;
    this.totalWaitTime += waitTime;

    try {
      // Check timeout
      if (request.timeout && waitTime > request.timeout) {
        throw new Error(`Request timeout: waited ${waitTime}ms, max ${request.timeout}ms`);
      }

      performanceMonitor.startRequest(request.id, this.model, request.flowName);
      const result = await request.operation();
      performanceMonitor.endRequest(request.id, true);

      request.resolve(result);
      this.totalProcessed++;
    } catch (error) {
      performanceMonitor.endRequest(
        request.id,
        false,
        error instanceof Error ? error.message : 'Unknown error'
      );
      request.reject(error instanceof Error ? error : new Error('Unknown error'));
    } finally {
      this.activeRequests--;
      // Process next request
      this.processNext();
    }
  }

  /**
   * Get queue statistics
   */
  getStats(): QueueStats {
    return {
      model: this.model,
      queuedRequests: this.queue.length,
      activeRequests: this.activeRequests,
      maxConcurrent: this.maxConcurrent,
      averageWaitTime: this.totalProcessed > 0 ? this.totalWaitTime / this.totalProcessed : 0,
      totalProcessed: this.totalProcessed,
    };
  }

  /**
   * Update max concurrent requests
   */
  setMaxConcurrent(max: number): void {
    this.maxConcurrent = max;
    // Try to process queued requests with new limit
    this.processNext();
  }

  /**
   * Clear queue
   */
  clear(): void {
    this.queue.forEach((req) => {
      req.reject(new Error('Queue cleared'));
    });
    this.queue = [];
  }

  /**
   * Get queue length
   */
  getQueueLength(): number {
    return this.queue.length;
  }

  /**
   * Get active request count
   */
  getActiveCount(): number {
    return this.activeRequests;
  }
}

/**
 * Global queue manager for all models
 */
class QueueManager {
  private queues: Map<string, ModelQueue> = new Map();

  constructor() {
    // Initialize queues for each model
    this.queues.set(OLLAMA_MODELS.GEMMA_2B, new ModelQueue(OLLAMA_MODELS.GEMMA_2B, 5));
    this.queues.set(OLLAMA_MODELS.PHI3_MINI, new ModelQueue(OLLAMA_MODELS.PHI3_MINI, 3));
    this.queues.set(OLLAMA_MODELS.LLAMA3_8B, new ModelQueue(OLLAMA_MODELS.LLAMA3_8B, 1));
  }

  /**
   * Execute request with queue management
   */
  async executeWithQueue<T>(
    requestId: string,
    model: string,
    flowName: string | undefined,
    operation: () => Promise<T>,
    priority: RequestPriority = RequestPriority.NORMAL,
    timeout?: number
  ): Promise<T> {
    let queue = this.queues.get(model);

    // Create queue if it doesn't exist
    if (!queue) {
      queue = new ModelQueue(model);
      this.queues.set(model, queue);
    }

    return queue.enqueue(requestId, flowName, operation, priority, timeout);
  }

  /**
   * Get statistics for all queues
   */
  getAllStats(): QueueStats[] {
    return Array.from(this.queues.values()).map((queue) => queue.getStats());
  }

  /**
   * Get statistics for specific model
   */
  getModelStats(model: string): QueueStats | null {
    const queue = this.queues.get(model);
    return queue ? queue.getStats() : null;
  }

  /**
   * Update max concurrent requests for a model
   */
  setMaxConcurrent(model: string, max: number): void {
    const queue = this.queues.get(model);
    if (queue) {
      queue.setMaxConcurrent(max);
    }
  }

  /**
   * Clear all queues
   */
  clearAll(): void {
    this.queues.forEach((queue) => queue.clear());
  }

  /**
   * Clear specific model queue
   */
  clearModel(model: string): void {
    const queue = this.queues.get(model);
    if (queue) {
      queue.clear();
    }
  }

  /**
   * Get total queued requests across all models
   */
  getTotalQueued(): number {
    return Array.from(this.queues.values()).reduce(
      (sum, queue) => sum + queue.getQueueLength(),
      0
    );
  }

  /**
   * Get total active requests across all models
   */
  getTotalActive(): number {
    return Array.from(this.queues.values()).reduce(
      (sum, queue) => sum + queue.getActiveCount(),
      0
    );
  }

  /**
   * Generate queue status report
   */
  generateReport(): string {
    const stats = this.getAllStats();

    let report = '📋 REQUEST QUEUE STATUS\n';
    report += '═══════════════════════════════════════\n\n';

    stats.forEach((stat) => {
      const modelName = stat.model.split('/')[1] || stat.model;
      report += `🤖 ${modelName.toUpperCase()}\n`;
      report += `   Queued: ${stat.queuedRequests} requests\n`;
      report += `   Active: ${stat.activeRequests}/${stat.maxConcurrent}\n`;
      report += `   Total Processed: ${stat.totalProcessed}\n`;
      report += `   Avg Wait Time: ${stat.averageWaitTime.toFixed(0)}ms\n`;

      // Status indicator
      const utilization = stat.activeRequests / stat.maxConcurrent;
      if (utilization >= 1.0) {
        report += `   Status: 🔴 FULL (${(utilization * 100).toFixed(0)}% utilization)\n`;
      } else if (utilization >= 0.7) {
        report += `   Status: 🟡 BUSY (${(utilization * 100).toFixed(0)}% utilization)\n`;
      } else {
        report += `   Status: 🟢 AVAILABLE (${(utilization * 100).toFixed(0)}% utilization)\n`;
      }

      report += '\n';
    });

    report += `📊 OVERALL: ${this.getTotalQueued()} queued, ${this.getTotalActive()} active\n`;

    return report;
  }

  /**
   * Check if model is available for immediate execution
   */
  isAvailable(model: string): boolean {
    const queue = this.queues.get(model);
    if (!queue) return true;

    const stats = queue.getStats();
    return stats.activeRequests < stats.maxConcurrent && stats.queuedRequests === 0;
  }

  /**
   * Get estimated wait time for a model
   */
  getEstimatedWaitTime(model: string): number {
    const queue = this.queues.get(model);
    if (!queue) return 0;

    const stats = queue.getStats();
    if (stats.queuedRequests === 0) return 0;

    // Estimate based on average wait time and queue position
    return stats.averageWaitTime * (stats.queuedRequests / stats.maxConcurrent);
  }
}

// Singleton instance
export const queueManager = new QueueManager();

/**
 * Helper function to execute request with automatic queue management
 */
export async function executeWithQueue<T>(
  requestId: string,
  model: string,
  flowName: string | undefined,
  operation: () => Promise<T>,
  options?: {
    priority?: RequestPriority;
    timeout?: number;
  }
): Promise<T> {
  return queueManager.executeWithQueue(
    requestId,
    model,
    flowName,
    operation,
    options?.priority || RequestPriority.NORMAL,
    options?.timeout
  );
}

/**
 * Check if a request should be queued
 */
export function shouldQueueRequest(model: string): boolean {
  return !queueManager.isAvailable(model);
}

/**
 * Get queue position for next request
 */
export function getQueuePosition(model: string): number {
  const stats = queueManager.getModelStats(model);
  return stats ? stats.queuedRequests + 1 : 1;
}
"}

{"file_path": "src/ai/model-health-check.ts", "initial_content": "/**
 * Model Health Check and Availability Monitoring
 * 
 * Monitors Ollama server and model availability, performs health checks,
 * and provides automatic fallback mechanisms.
 */

import { OLLAMA_MODELS } from './genkit';
import { getFallbackModel } from './model-selector';

/**
 * Health status for a model
 */
export enum HealthStatus {
  HEALTHY = 'healthy',
  DEGRADED = 'degraded',
  UNHEALTHY = 'unhealthy',
  UNAVAILABLE = 'unavailable',
}

/**
 * Health check result
 */
export interface HealthCheckResult {
  model: string;
  status: HealthStatus;
  responseTime?: number;
  lastChecked: number;
  error?: string;
  available: boolean;
}

/**
 * Server health information
 */
export interface ServerHealth {
  serverUrl: string;
  online: boolean;
  lastChecked: number;
  models: HealthCheckResult[];
  overallStatus: HealthStatus;
}

/**
 * Health check configuration
 */
interface HealthCheckConfig {
  serverUrl: string;
  checkInterval: number; // ms
  timeout: number; // ms
  retryAttempts: number;
}

/**
 * Model health monitor
 */
class ModelHealthMonitor {
  private config: HealthCheckConfig;
  private healthCache: Map<string, HealthCheckResult> = new Map();
  private serverOnline = true;
  private lastServerCheck = 0;
  private checkInterval?: NodeJS.Timeout;

  constructor(config: Partial<HealthCheckConfig> = {}) {
    this.config = {
      serverUrl: 'http://185.190.140.93:11434',
      checkInterval: 60000, // 1 minute
      timeout: 5000, // 5 seconds
      retryAttempts: 3,
      ...config,
    };
  }

  /**
   * Perform health check for a specific model
   */
  async checkModel(model: string): Promise<HealthCheckResult> {
    const startTime = Date.now();
    const modelName = model.replace('ollama/', '');

    try {
      // Try to generate a simple response
      const response = await this.testGeneration(modelName);

      const responseTime = Date.now() - startTime;
      const result: HealthCheckResult = {
        model,
        status: this.determineStatus(responseTime),
        responseTime,
        lastChecked: Date.now(),
        available: true,
      };

      this.healthCache.set(model, result);
      return result;
    } catch (error) {
      const result: HealthCheckResult = {
        model,
        status: HealthStatus.UNAVAILABLE,
        lastChecked: Date.now(),
        error: error instanceof Error ? error.message : 'Unknown error',
        available: false,
      };

      this.healthCache.set(model, result);
      return result;
    }
  }

  /**
   * Test generation with a model
   */
  private async testGeneration(modelName: string): Promise<boolean> {
    // Simple test: generate a single word
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), this.config.timeout);

    try {
      const response = await fetch(`${this.config.serverUrl}/api/generate`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: modelName,
          prompt: 'Say "ok"',
          stream: false,
        }),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);
      return response.ok;
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  }

  /**
   * Determine health status based on response time
   */
  private determineStatus(responseTime: number): HealthStatus {
    if (responseTime < 2000) return HealthStatus.HEALTHY;
    if (responseTime < 5000) return HealthStatus.DEGRADED;
    return HealthStatus.UNHEALTHY;
  }

  /**
   * Check all models
   */
  async checkAllModels(): Promise<HealthCheckResult[]> {
    const models = [OLLAMA_MODELS.GEMMA_2B, OLLAMA_MODELS.PHI3_MINI, OLLAMA_MODELS.LLAMA3_8B];
    const results = await Promise.all(models.map((model) => this.checkModel(model)));
    return results;
  }

  /**
   * Check server availability
   */
  async checkServer(): Promise<boolean> {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), this.config.timeout);

      const response = await fetch(`${this.config.serverUrl}/api/tags`, {
        method: 'GET',
        signal: controller.signal,
      });

      clearTimeout(timeoutId);
      this.serverOnline = response.ok;
      this.lastServerCheck = Date.now();
      return this.serverOnline;
    } catch (error) {
      this.serverOnline = false;
      this.lastServerCheck = Date.now();
      return false;
    }
  }

  /**
   * Get cached health status
   */
  getHealthStatus(model: string): HealthCheckResult | null {
    return this.healthCache.get(model) || null;
  }

  /**
   * Get all cached health statuses
   */
  getAllHealthStatuses(): HealthCheckResult[] {
    return Array.from(this.healthCache.values());
  }

  /**
   * Check if model is available
   */
  isModelAvailable(model: string): boolean {
    const health = this.healthCache.get(model);
    if (!health) return true; // Assume available if not checked yet

    // Consider available if status is healthy or degraded
    return health.status === HealthStatus.HEALTHY || health.status === HealthStatus.DEGRADED;
  }

  /**
   * Get server health information
   */
  async getServerHealth(): Promise<ServerHealth> {
    const serverOnline = await this.checkServer();
    const modelResults = await this.checkAllModels();

    // Determine overall status
    let overallStatus = HealthStatus.HEALTHY;
    if (!serverOnline) {
      overallStatus = HealthStatus.UNAVAILABLE;
    } else {
      const unhealthyCount = modelResults.filter(
        (r) => r.status === HealthStatus.UNHEALTHY || r.status === HealthStatus.UNAVAILABLE
      ).length;

      if (unhealthyCount === modelResults.length) {
        overallStatus = HealthStatus.UNAVAILABLE;
      } else if (unhealthyCount > 0) {
        overallStatus = HealthStatus.DEGRADED;
      }
    }

    return {
      serverUrl: this.config.serverUrl,
      online: serverOnline,
      lastChecked: Date.now(),
      models: modelResults,
      overallStatus,
    };
  }

  /**
   * Start periodic health checks
   */
  startPeriodicChecks(): void {
    if (this.checkInterval) return;

    // Initial check
    this.checkAllModels();

    // Periodic checks
    this.checkInterval = setInterval(async () => {
      await this.checkAllModels();
    }, this.config.checkInterval);
  }

  /**
   * Stop periodic health checks
   */
  stopPeriodicChecks(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = undefined;
    }
  }

  /**
   * Generate health report
   */
  async generateHealthReport(): Promise<string> {
    const serverHealth = await this.getServerHealth();

    let report = '🏥 MODEL HEALTH STATUS\n';
    report += '═══════════════════════════════════════\n\n';

    report += `🌐 Server: ${serverHealth.serverUrl}\n`;
    report += `   Status: ${serverHealth.online ? '🟢 ONLINE' : '🔴 OFFLINE'}\n`;
    report += `   Overall: ${this.getStatusEmoji(serverHealth.overallStatus)} ${serverHealth.overallStatus.toUpperCase()}\n\n`;

    report += '📊 MODEL STATUS:\n\n';

    serverHealth.models.forEach((model) => {
      const modelName = model.model.split('/')[1] || model.model;
      report += `🤖 ${modelName.toUpperCase()}\n`;
      report += `   Status: ${this.getStatusEmoji(model.status)} ${model.status.toUpperCase()}\n`;
      report += `   Available: ${model.available ? '✅ Yes' : '❌ No'}\n`;

      if (model.responseTime) {
        report += `   Response Time: ${model.responseTime.toFixed(0)}ms\n`;
      }

      if (model.error) {
        report += `   Error: ${model.error}\n`;
      }

      const cacheAge = Date.now() - model.lastChecked;
      report += `   Last Checked: ${this.formatAge(cacheAge)} ago\n`;
      report += '\n';
    });

    return report;
  }

  /**
   * Get emoji for status
   */
  private getStatusEmoji(status: HealthStatus): string {
    switch (status) {
      case HealthStatus.HEALTHY:
        return '🟢';
      case HealthStatus.DEGRADED:
        return '🟡';
      case HealthStatus.UNHEALTHY:
        return '🟠';
      case HealthStatus.UNAVAILABLE:
        return '🔴';
      default:
        return '⚪';
    }
  }

  /**
   * Format age in human-readable format
   */
  private formatAge(ms: number): string {
    const seconds = Math.floor(ms / 1000);
    if (seconds < 60) return `${seconds}s`;

    const minutes = Math.floor(seconds / 60);
    if (minutes < 60) return `${minutes}m`;

    const hours = Math.floor(minutes / 60);
    return `${hours}h`;
  }

  /**
   * Update configuration
   */
  updateConfig(config: Partial<HealthCheckConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Clear health cache
   */
  clearCache(): void {
    this.healthCache.clear();
  }
}

// Singleton instance
export const healthMonitor = new ModelHealthMonitor();

/**
 * Check if model is healthy and available
 */
export async function isModelHealthy(model: string): Promise<boolean> {
  const result = await healthMonitor.checkModel(model);
  return result.available && result.status !== HealthStatus.UNAVAILABLE;
}

/**
 * Get available model with fallback
 */
export async function getAvailableModel(preferredModel: string): Promise<string> {
  const isHealthy = await isModelHealthy(preferredModel);

  if (isHealthy) {
    return preferredModel;
  }

  // Try fallback
  const fallback = getFallbackModel(preferredModel);
  const fallbackHealthy = await isModelHealthy(fallback);

  if (fallbackHealthy) {
    console.warn(`Model ${preferredModel} unavailable, using fallback: ${fallback}`);
    return fallback;
  }

  // If fallback also fails, return preferred (let it fail with proper error)
  console.error(`Both ${preferredModel} and fallback ${fallback} are unavailable`);
  return preferredModel;
}

/**
 * Execute with automatic fallback
 */
export async function executeWithFallback<T>(
  model: string,
  operation: (model: string) => Promise<T>,
  maxRetries = 2
): Promise<T> {
  let currentModel = model;
  let attempts = 0;

  while (attempts <= maxRetries) {
    try {
      // Check if model is healthy before attempting
      if (attempts > 0) {
        currentModel = await getAvailableModel(currentModel);
      }

      return await operation(currentModel);
    } catch (error) {
      attempts++;

      if (attempts > maxRetries) {
        throw error;
      }

      // Try fallback on next attempt
      const fallback = getFallbackModel(currentModel);
      console.warn(`Attempt ${attempts} failed with ${currentModel}, trying fallback: ${fallback}`);
      currentModel = fallback;
    }
  }

  throw new Error('All attempts failed');
}

/**
 * Start monitoring (call this at app startup)
 */
export function startHealthMonitoring(intervalMs = 60000): void {
  healthMonitor.updateConfig({ checkInterval: intervalMs });
  healthMonitor.startPeriodicChecks();
}

/**
 * Stop monitoring (call this at app shutdown)
 */
export function stopHealthMonitoring(): void {
  healthMonitor.stopPeriodicChecks();
}
"}

{"file_path": "src/ai/model-utils.ts", "initial_content": "/**
 * Model Utility Functions
 * 
 * Collection of utility functions for working with AI models,
 * including token counting, cost estimation, and optimization helpers.
 */

import { OLLAMA_MODELS } from './genkit';

/**
 * Estimate token count from text
 * Approximation: 1 token ≈ 4 characters for English, 1-2 characters for Arabic
 */
export function estimateTokenCount(text: string, language: 'en' | 'ar' | 'auto' = 'auto'): number {
  if (!text) return 0;

  // Detect language if auto
  let detectedLanguage = language;
  if (language === 'auto') {
    // Simple heuristic: if more than 30% Arabic characters, treat as Arabic
    const arabicChars = text.match(/[\u0600-\u06FF]/g) || [];
    detectedLanguage = arabicChars.length / text.length > 0.3 ? 'ar' : 'en';
  }

  // Token estimation
  if (detectedLanguage === 'ar') {
    // Arabic: ~1.5 characters per token
    return Math.ceil(text.length / 1.5);
  } else {
    // English: ~4 characters per token
    return Math.ceil(text.length / 4);
  }
}

/**
 * Estimate memory usage for a request
 */
export function estimateMemoryUsage(model: string, inputTokens: number): number {
  // Base memory usage per model (MB)
  const baseMemory: Record<string, number> = {
    [OLLAMA_MODELS.GEMMA_2B]: 2500,
    [OLLAMA_MODELS.PHI3_MINI]: 3300,
    [OLLAMA_MODELS.LLAMA3_8B]: 4700,
  };

  const base = baseMemory[model] || 2000;

  // Add memory for context (rough estimate: 1MB per 1000 tokens)
  const contextMemory = Math.ceil(inputTokens / 1000);

  return base + contextMemory;
}

/**
 * Check if input is within safe token limits
 */
export function isWithinTokenLimit(text: string, maxTokens: number): boolean {
  const tokens = estimateTokenCount(text);
  return tokens <= maxTokens;
}

/**
 * Truncate text to fit within token limit
 */
export function truncateToTokenLimit(text: string, maxTokens: number): string {
  const estimatedTokens = estimateTokenCount(text);

  if (estimatedTokens <= maxTokens) {
    return text;
  }

  // Calculate characters to keep (rough estimate)
  const ratio = maxTokens / estimatedTokens;
  const targetLength = Math.floor(text.length * ratio);

  // Try to truncate at sentence boundary
  const truncated = text.substring(0, targetLength);
  const lastPeriod = truncated.lastIndexOf('.');
  const lastNewline = truncated.lastIndexOf('\n');

  const breakpoint = Math.max(lastPeriod, lastNewline);
  if (breakpoint > targetLength * 0.8) {
    return truncated.substring(0, breakpoint + 1);
  }

  return truncated + '...';
}

/**
 * Split text into chunks that fit within token limit
 */
export function chunkText(text: string, maxTokensPerChunk: number, overlap = 0): string[] {
  const paragraphs = text.split(/\n\n+/);
  const chunks: string[] = [];
  let currentChunk = '';
  let currentTokens = 0;

  for (const paragraph of paragraphs) {
    const paragraphTokens = estimateTokenCount(paragraph);

    // If single paragraph exceeds limit, split it
    if (paragraphTokens > maxTokensPerChunk) {
      if (currentChunk) {
        chunks.push(currentChunk.trim());
        currentChunk = '';
        currentTokens = 0;
      }

      // Split large paragraph by sentences
      const sentences = paragraph.split(/[.!?]+\s+/);
      for (const sentence of sentences) {
        const sentenceTokens = estimateTokenCount(sentence);

        if (currentTokens + sentenceTokens > maxTokensPerChunk) {
          chunks.push(currentChunk.trim());
          currentChunk = sentence;
          currentTokens = sentenceTokens;
        } else {
          currentChunk += (currentChunk ? ' ' : '') + sentence;
          currentTokens += sentenceTokens;
        }
      }
    } else {
      // Check if adding paragraph exceeds limit
      if (currentTokens + paragraphTokens > maxTokensPerChunk) {
        chunks.push(currentChunk.trim());
        currentChunk = paragraph;
        currentTokens = paragraphTokens;
      } else {
        currentChunk += (currentChunk ? '\n\n' : '') + paragraph;
        currentTokens += paragraphTokens;
      }
    }
  }

  // Add remaining chunk
  if (currentChunk.trim()) {
    chunks.push(currentChunk.trim());
  }

  // Add overlap if specified
  if (overlap > 0 && chunks.length > 1) {
    return addOverlapToChunks(chunks, overlap);
  }

  return chunks;
}

/**
 * Add overlap between chunks
 */
function addOverlapToChunks(chunks: string[], overlapTokens: number): string[] {
  const overlappedChunks: string[] = [chunks[0]];

  for (let i = 1; i < chunks.length; i++) {
    const prevChunk = chunks[i - 1];
    const currentChunk = chunks[i];

    // Get last part of previous chunk for overlap
    const overlapText = getLastTokens(prevChunk, overlapTokens);
    overlappedChunks.push(overlapText + '\n\n' + currentChunk);
  }

  return overlappedChunks;
}

/**
 * Get last N tokens from text (approximate)
 */
function getLastTokens(text: string, tokenCount: number): string {
  const estimatedTokens = estimateTokenCount(text);
  if (estimatedTokens <= tokenCount) return text;

  const ratio = tokenCount / estimatedTokens;
  const startIndex = Math.floor(text.length * (1 - ratio));

  return '...' + text.substring(startIndex);
}

/**
 * Optimize prompt for model
 */
export function optimizePromptForModel(prompt: string, model: string): string {
  // For Gemma 2B: Keep prompts simple and direct
  if (model === OLLAMA_MODELS.GEMMA_2B) {
    return simplifyPrompt(prompt);
  }

  // For Phi-3 Mini: Add structure hints
  if (model === OLLAMA_MODELS.PHI3_MINI) {
    return addStructureHints(prompt);
  }

  // For Llama 3 8B: Can handle complex prompts
  return prompt;
}

/**
 * Simplify prompt for lighter models
 */
function simplifyPrompt(prompt: string): string {
  // Remove excessive formatting
  let simplified = prompt
    .replace(/\*\*\*+/g, '**') // Reduce excessive bold
    .replace(/---+/g, '---') // Simplify dividers
    .replace(/\n{3,}/g, '\n\n'); // Reduce excessive newlines

  return simplified;
}

/**
 * Add structure hints for Phi-3 Mini
 */
function addStructureHints(prompt: string): string {
  // Phi-3 benefits from clear structure indicators
  if (!prompt.includes('Output format:') && !prompt.includes('JSON')) {
    return prompt + '\n\nProvide a clear, structured response.';
  }
  return prompt;
}

/**
 * Get model-specific recommendations
 */
export interface ModelRecommendations {
  maxInputTokens: number;
  maxOutputTokens: number;
  optimalTemperature: number;
  useRAG: boolean;
  chunkLargeInputs: boolean;
  recommendations: string[];
}

export function getModelRecommendations(model: string): ModelRecommendations {
  switch (model) {
    case OLLAMA_MODELS.GEMMA_2B:
      return {
        maxInputTokens: 2048,
        maxOutputTokens: 512,
        optimalTemperature: 0.7,
        useRAG: false,
        chunkLargeInputs: true,
        recommendations: [
          'Keep prompts simple and direct',
          'Limit output to 200-300 words',
          'Best for text generation and conversion',
          'Can handle multiple concurrent requests',
        ],
      };

    case OLLAMA_MODELS.PHI3_MINI:
      return {
        maxInputTokens: 4096,
        maxOutputTokens: 1024,
        optimalTemperature: 0.5,
        useRAG: false,
        chunkLargeInputs: false,
        recommendations: [
          'Excellent for structured output',
          'Use clear formatting instructions',
          'Best for analysis and reports',
          'Limit to 2-3 concurrent requests',
        ],
      };

    case OLLAMA_MODELS.LLAMA3_8B:
      return {
        maxInputTokens: 8192,
        maxOutputTokens: 2048,
        optimalTemperature: 0.7,
        useRAG: true,
        chunkLargeInputs: false,
        recommendations: [
          'Always use with RAG for academic tasks',
          'Provide 500-1000 tokens of context',
          'Best for complex reasoning',
          'Run one request at a time',
          'Limit output to 300 words per generation',
        ],
      };

    default:
      return {
        maxInputTokens: 2048,
        maxOutputTokens: 512,
        optimalTemperature: 0.7,
        useRAG: false,
        chunkLargeInputs: true,
        recommendations: ['Use default settings'],
      };
  }
}

/**
 * Calculate optimal chunk size for model
 */
export function getOptimalChunkSize(model: string): number {
  const recommendations = getModelRecommendations(model);
  // Use 80% of max input tokens to leave room for prompt
  return Math.floor(recommendations.maxInputTokens * 0.8);
}

/**
 * Validate model configuration
 */
export interface ModelConfigValidation {
  valid: boolean;
  warnings: string[];
  errors: string[];
}

export function validateModelConfig(
  model: string,
  inputText: string,
  maxOutputTokens?: number,
  temperature?: number
): ModelConfigValidation {
  const warnings: string[] = [];
  const errors: string[] = [];
  const recommendations = getModelRecommendations(model);

  // Check input size
  const inputTokens = estimateTokenCount(inputText);
  if (inputTokens > recommendations.maxInputTokens) {
    errors.push(
      `Input too large: ${inputTokens} tokens exceeds ${recommendations.maxInputTokens} limit for ${model}`
    );
  } else if (inputTokens > recommendations.maxInputTokens * 0.8) {
    warnings.push(`Input size is ${Math.round((inputTokens / recommendations.maxInputTokens) * 100)}% of limit`);
  }

  // Check output size
  if (maxOutputTokens && maxOutputTokens > recommendations.maxOutputTokens) {
    warnings.push(
      `Requested output (${maxOutputTokens} tokens) exceeds recommended ${recommendations.maxOutputTokens} for ${model}`
    );
  }

  // Check temperature
  if (temperature !== undefined) {
    if (temperature < 0 || temperature > 2) {
      errors.push(`Temperature ${temperature} is out of valid range (0-2)`);
    } else if (Math.abs(temperature - recommendations.optimalTemperature) > 0.5) {
      warnings.push(
        `Temperature ${temperature} differs significantly from optimal ${recommendations.optimalTemperature} for ${model}`
      );
    }
  }

  // Model-specific checks
  if (model === OLLAMA_MODELS.LLAMA3_8B && inputTokens < 500 && recommendations.useRAG) {
    warnings.push('Llama 3 8B works best with RAG context (500+ tokens recommended)');
  }

  return {
    valid: errors.length === 0,
    warnings,
    errors,
  };
}

/**
 * Format model name for display
 */
export function formatModelName(model: string): string {
  const name = model.replace('ollama/', '');
  return name
    .split(/[:-]/)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

/**
 * Get model nickname
 */
export function getModelNickname(model: string): string {
  switch (model) {
    case OLLAMA_MODELS.GEMMA_2B:
      return 'Fast';
    case OLLAMA_MODELS.PHI3_MINI:
      return 'Smart';
    case OLLAMA_MODELS.LLAMA3_8B:
      return 'Quality';
    default:
      return 'Unknown';
  }
}

/**
 * Compare model capabilities
 */
export function compareModelCapabilities(model1: string, model2: string): {
  faster: string;
  smarter: string;
  largerContext: string;
  moreEfficient: string;
} {
  const rec1 = getModelRecommendations(model1);
  const rec2 = getModelRecommendations(model2);

  return {
    faster: rec1.maxInputTokens < rec2.maxInputTokens ? model1 : model2,
    smarter: rec1.maxInputTokens > rec2.maxInputTokens ? model1 : model2,
    largerContext: rec1.maxInputTokens > rec2.maxInputTokens ? model1 : model2,
    moreEfficient: rec1.maxInputTokens < rec2.maxInputTokens ? model1 : model2,
  };
}
"}

