export async function example2_performanceMonitoring() {
  console.log('Example 2: Performance Monitoring\n');

  const requestId = generateRequestId();
  const model = OLLAMA_MODELS.PHI3_MINI;

  // Track a request
  const result = await trackRequest(
    requestId,
    model,
    'grammar-checker',
    async () => {
      // Simulate operation
