{"file_path": "src/lib/models/flow-config.ts", "initial_content": "/**
 * Flow Configuration Models
 * 
 * Defines TypeScript interfaces and types for dynamic flow configurations
 * stored in Firestore database.
 */

import { Timestamp } from 'firebase/firestore';

/**
 * Flow configuration status
 */
export type FlowStatus = 'draft' | 'active' | 'archived';

/**
 * Step types supported by the dynamic executor
 */
export type StepType = 'RETRIEVE' | 'GENERATE' | 'TOOL' | 'FORMAT' | 'CONDITION' | 'LOOP';

/**
 * Error handling strategies for steps
 */
export type ErrorHandlingStrategy = 'stop' | 'skip' | 'retry';

/**
 * Main flow configuration interface
 */
export interface FlowConfiguration {
  id: string;
  name: string;
  displayName: string;
  description: string;
  version: number;
  status: FlowStatus;
  category: string;
  tags: string[];

  // Step definitions
  steps: FlowStep[];

  // Schema definitions (Zod schema as JSON)
  inputSchema: Record<string, any>;
  outputSchema: Record<string, any>;

  // Metadata
  createdBy: string;
  createdAt: Timestamp;
  updatedAt: Timestamp;
  publishedAt?: Timestamp;

  // Settings
  settings: FlowSettings;
}

/**
 * Individual step in a flow
 */
export interface FlowStep {
  id: string;
  type: StepType;
  name: string;
  description?: string;

  // Configuration based on step type
  config: StepConfig;

  // I/O Schema (Zod schema as JSON)
  inputSchema: Record<string, any>;
  outputSchema: Record<string, any>;

  // Data mapping between context and step
  inputMapping?: Record<string, string>; // Map context vars to step inputs
  outputMapping?: Record<string, string>; // Map step outputs to context vars

  // Error handling
  onError?: ErrorHandlingStrategy;
  retryCount?: number;
  retryDelay?: number; // milliseconds

  // Conditional execution
  condition?: string; // JavaScript expression
}

/**
 * Union type for all step configurations
 */
export type StepConfig = 
  | RetrieveStepConfig
  | GenerateStepConfig
  | ToolStepConfig
  | FormatStepConfig
  | ConditionStepConfig
  | LoopStepConfig;

/**
 * Configuration for RETRIEVE step (RAG retrieval)
 */
export interface RetrieveStepConfig {
  type: 'RETRIEVE';
  retrieverName: string; // Name of registered retriever
  query: string; // Template string with {{variables}}
  topK?: number;
  minScore?: number;
  metadata?: Record<string, any>;
}

/**
 * Configuration for GENERATE step (LLM generation)
 */
export interface GenerateStepConfig {
  type: 'GENERATE';
  promptId: string; // Reference to prompt template in database
  model?: string; // Override default model
  temperature?: number;
  maxTokens?: number;
  topP?: number;
  streamResponse?: boolean;
}

/**
 * Configuration for TOOL step (external tool execution)
 */
export interface ToolStepConfig {
  type: 'TOOL';
  toolName: string; // Name of registered tool
  parameters: Record<string, any>; // Tool-specific parameters
  timeout?: number;
}

/**
 * Configuration for FORMAT step (output formatting)
 */
export interface FormatStepConfig {
  type: 'FORMAT';
  outputFormat: 'json' | 'markdown' | 'html' | 'text' | 'xml';
  template?: string; // Template string for custom formatting
  prettify?: boolean;
}

/**
 * Configuration for CONDITION step (conditional branching)
 */
export interface ConditionStepConfig {
  type: 'CONDITION';
  condition: string; // JavaScript expression
  trueSteps: FlowStep[]; // Steps to execute if condition is true
  falseSteps?: FlowStep[]; // Steps to execute if condition is false
}

/**
 * Configuration for LOOP step (iterative processing)
 */
export interface LoopStepConfig {
  type: 'LOOP';
  itemsSource: string; // Context variable containing array
  itemVariable: string; // Variable name for current iteration item
  indexVariable?: string; // Variable name for current index
  steps: FlowStep[]; // Steps to execute for each item
  maxIterations?: number; // Safety limit
  parallel?: boolean; // Execute iterations in parallel
}

/**
 * Flow execution settings
 */
export interface FlowSettings {
  // Performance
  timeout?: number; // milliseconds, default 300000 (5 min)
  maxRetries?: number; // Global retry count

  // Caching
  enableCaching?: boolean;
  cacheTTL?: number; // seconds
  cacheKeyTemplate?: string; // Template for cache key

  // Tracing & Monitoring
  enableTracing?: boolean;
  logLevel?: 'debug' | 'info' | 'warn' | 'error';

  // Security
  requiresAuth?: boolean;
  allowedRoles?: string[];
  allowedUsers?: string[];

  // Rate Limiting
  rateLimitPerMinute?: number;
  rateLimitPerHour?: number;

  // Advanced
  concurrencyLimit?: number; // Max concurrent executions
  priority?: number; // Execution priority (higher = more important)
}

/**
 * Flow version history entry
 */
export interface FlowVersion {
  flowId: string;
  version: number;
  configuration: FlowConfiguration;
  createdBy: string;
  createdAt: Timestamp;
  message?: string; // Commit message
  previousVersion?: number;
}

/**
 * Flow execution context snapshot
 */
export interface FlowExecutionContext {
  flowId: string;
  flowVersion: number;
  executionId: string;
  startTime: Timestamp;

  // Current state
  currentStepId?: string;
  currentStepIndex?: number;

  // Context data
  variables: Record<string, any>;
  stepOutputs: Record<string, any>;

  // Status
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  error?: string;
}

/**
 * Flow execution result
 */
export interface FlowExecutionResult {
  executionId: string;
  flowId: string;
  flowVersion: number;

  status: 'completed' | 'failed';
  output?: any;
  error?: {
    message: string;
    step?: string;
    stack?: string;
  };

  // Timing
  startTime: Timestamp;
  endTime: Timestamp;
  duration: number; // milliseconds

  // Metadata
  userId?: string;
  requestId?: string;
  traceId?: string;
}

/**
 * Type guard to check step config type
 */
export function isRetrieveStep(config: StepConfig): config is RetrieveStepConfig {
  return config.type === 'RETRIEVE';
}

export function isGenerateStep(config: StepConfig): config is GenerateStepConfig {
  return config.type === 'GENERATE';
}

export function isToolStep(config: StepConfig): config is ToolStepConfig {
  return config.type === 'TOOL';
}

export function isFormatStep(config: StepConfig): config is FormatStepConfig {
  return config.type === 'FORMAT';
}

export function isConditionStep(config: StepConfig): config is ConditionStepConfig {
  return config.type === 'CONDITION';
}

export function isLoopStep(config: StepConfig): config is LoopStepConfig {
  return config.type === 'LOOP';
}

/**
 * Firestore collection names
 */
export const FLOW_COLLECTIONS = {
  CONFIGURATIONS: 'flowConfigurations',
  VERSIONS: 'flowVersions',
  EXECUTIONS: 'flowExecutions',
} as const;

/**
 * Default flow settings
 */
export const DEFAULT_FLOW_SETTINGS: FlowSettings = {
  timeout: 300000, // 5 minutes
  maxRetries: 3,
  enableCaching: false,
  enableTracing: true,
  logLevel: 'info',
  requiresAuth: true,
  rateLimitPerMinute: 60,
  concurrencyLimit: 10,
  priority: 5,
};

/**
 * Validation helpers
 */
export function validateFlowConfiguration(config: Partial<FlowConfiguration>): string[] {
  const errors: string[] = [];

  if (!config.name) {
    errors.push('Flow name is required');
  }

  if (!config.displayName) {
    errors.push('Flow display name is required');
  }

  if (!config.steps || config.steps.length === 0) {
    errors.push('Flow must have at least one step');
  }

  if (!config.inputSchema) {
    errors.push('Flow input schema is required');
  }

  if (!config.outputSchema) {
    errors.push('Flow output schema is required');
  }

  // Validate step IDs are unique
  if (config.steps) {
    const stepIds = config.steps.map(s => s.id);
    const uniqueIds = new Set(stepIds);
    if (stepIds.length !== uniqueIds.size) {
      errors.push('Step IDs must be unique');
    }
  }

  return errors;
}

/**
 * Create a new flow configuration with defaults
 */
export function createFlowConfiguration(
  partial: Partial<FlowConfiguration>
): Omit<FlowConfiguration, 'id' | 'createdAt' | 'updatedAt'> {
  return {
    name: partial.name || '',
    displayName: partial.displayName || '',
    description: partial.description || '',
    version: 1,
    status: 'draft',
    category: partial.category || 'general',
    tags: partial.tags || [],
    steps: partial.steps || [],
    inputSchema: partial.inputSchema || {},
    outputSchema: partial.outputSchema || {},
    createdBy: partial.createdBy || '',
    settings: { ...DEFAULT_FLOW_SETTINGS, ...partial.settings },
  } as Omit<FlowConfiguration, 'id' | 'createdAt' | 'updatedAt'>;
}
"}

{"file_path": "src/lib/models/prompt-config.ts", "initial_content": "/**
 * Prompt Configuration Models
 * 
 * Defines TypeScript interfaces for dynamic prompt templates
 * stored in Firestore database.
 */

import { Timestamp } from 'firebase/firestore';

/**
 * Prompt variable types
 */
export type PromptVariableType = 'string' | 'number' | 'boolean' | 'array' | 'object';

/**
 * Prompt configuration status
 */
export type PromptStatus = 'draft' | 'active' | 'archived';

/**
 * Main prompt configuration interface
 */
export interface PromptConfiguration {
  id: string;
  name: string;
  displayName: string;
  description: string;
  category: string;
  tags: string[];

  // Template content with variable placeholders
  templateContent: string; // Uses {{variable}} syntax
  systemPrompt?: string; // System/instruction prompt

  // Variables used in the template
  variables: PromptVariable[];

  // Schema definitions (Zod schema as JSON)
  inputSchema: Record<string, any>;
  outputSchema: Record<string, any>;

  // Metadata
  version: number;
  status: PromptStatus;
  createdBy: string;
  createdAt: Timestamp;
  updatedAt: Timestamp;
  publishedAt?: Timestamp;

  // Testing
  testCases?: PromptTestCase[];

  // Model preferences
  preferredModel?: string;
  fallbackModel?: string;

  // Settings
  settings?: PromptSettings;
}

/**
 * Variable definition in a prompt
 */
export interface PromptVariable {
  name: string;
  type: PromptVariableType;
  description: string;
  required: boolean;
  defaultValue?: any;

  // Validation
  validation?: PromptVariableValidation;

  // UI hints
  placeholder?: string;
  examples?: any[];
}

/**
 * Validation rules for prompt variables
 */
export interface PromptVariableValidation {
  // String validation
  minLength?: number;
  maxLength?: number;
  pattern?: string; // Regex pattern

  // Number validation
  min?: number;
  max?: number;
  integer?: boolean;

  // Array validation
  minItems?: number;
  maxItems?: number;
  uniqueItems?: boolean;

  // Enum validation
  enum?: any[];

  // Custom validation message
  message?: string;
}

/**
 * Test case for prompt validation
 */
export interface PromptTestCase {
  id: string;
  name: string;
  description?: string;

  // Test input
  input: Record<string, any>;

  // Expected output (optional for validation)
  expectedOutput?: string;
  expectedPattern?: string; // Regex pattern for output validation

  // Test results
  lastRunAt?: Timestamp;
  passed?: boolean;
  actualOutput?: string;
  error?: string;
  duration?: number;
}

/**
 * Prompt execution settings
 */
export interface PromptSettings {
  // Generation parameters
  temperature?: number;
  maxTokens?: number;
  topP?: number;
  frequencyPenalty?: number;
  presencePenalty?: number;

  // Safety
  stopSequences?: string[];

  // Formatting
  trimWhitespace?: boolean;
  removeEmptyLines?: boolean;

  // Caching
  cacheable?: boolean;
  cacheTTL?: number; // seconds
}

/**
 * Prompt version history entry
 */
export interface PromptVersion {
  promptId: string;
  version: number;
  configuration: PromptConfiguration;
  createdBy: string;
  createdAt: Timestamp;
  message?: string; // Commit message
  previousVersion?: number;

  // Performance metrics
  averageTokens?: number;
  averageDuration?: number;
  successRate?: number;
}

/**
 * Prompt usage statistics
 */
export interface PromptUsageStats {
  promptId: string;
  period: 'hour' | 'day' | 'week' | 'month';
  startDate: Timestamp;
  endDate: Timestamp;

  // Usage metrics
  executionCount: number;
  successCount: number;
  failureCount: number;

  // Performance metrics
  averageDuration: number;
  p95Duration: number;
  averageInputTokens: number;
  averageOutputTokens: number;

  // Quality metrics
  averageRating?: number;
  feedbackCount?: number;
}

/**
 * Prompt execution context
 */
export interface PromptExecutionContext {
  promptId: string;
  promptVersion: number;
  executionId: string;

  // Input
  variables: Record<string, any>;

  // Model settings
  model: string;
  temperature?: number;
  maxTokens?: number;

  // Metadata
  userId?: string;
  flowId?: string;
  stepId?: string;
}

/**
 * Prompt execution result
 */
export interface PromptExecutionResult {
  executionId: string;
  promptId: string;
  promptVersion: number;

  // Output
  output: string;
  renderedPrompt: string; // Final prompt with variables replaced

  // Metadata
  model: string;
  tokenUsage: {
    input: number;
    output: number;
    total: number;
  };

  // Timing
  startTime: Timestamp;
  endTime: Timestamp;
  duration: number;

  // Status
  status: 'success' | 'error';
  error?: string;
}

/**
 * Firestore collection names
 */
export const PROMPT_COLLECTIONS = {
  CONFIGURATIONS: 'promptTemplates',
  VERSIONS: 'promptVersions',
  EXECUTIONS: 'promptExecutions',
  STATS: 'promptStats',
} as const;

/**
 * Default prompt settings
 */
export const DEFAULT_PROMPT_SETTINGS: PromptSettings = {
  temperature: 0.7,
  maxTokens: 2048,
  topP: 1.0,
  trimWhitespace: true,
  removeEmptyLines: false,
  cacheable: true,
  cacheTTL: 3600, // 1 hour
};

/**
 * Template syntax patterns
 */
export const TEMPLATE_PATTERNS = {
  VARIABLE: /\{\{([^}]+)\}\}/g, // Matches {{variable}}
  CONDITIONAL: /\{\{#if\s+([^}]+)\}\}([\s\S]*?)\{\{\/if\}\}/g, // Matches {{#if condition}}...{{/if}}
  LOOP: /\{\{#each\s+([^}]+)\}\}([\s\S]*?)\{\{\/each\}\}/g, // Matches {{#each items}}...{{/each}}
} as const;

/**
 * Validation helpers
 */
export function validatePromptConfiguration(config: Partial<PromptConfiguration>): string[] {
  const errors: string[] = [];

  if (!config.name) {
    errors.push('Prompt name is required');
  }

  if (!config.displayName) {
    errors.push('Prompt display name is required');
  }

  if (!config.templateContent) {
    errors.push('Prompt template content is required');
  }

  if (!config.variables || config.variables.length === 0) {
    errors.push('Prompt must have at least one variable');
  }

  // Validate variables in template match variable definitions
  if (config.templateContent && config.variables) {
    const templateVars = extractVariablesFromTemplate(config.templateContent);
    const definedVars = new Set(config.variables.map(v => v.name));

    const undefinedVars = templateVars.filter(v => !definedVars.has(v));
    if (undefinedVars.length > 0) {
      errors.push(`Template uses undefined variables: ${undefinedVars.join(', ')}`);
    }
  }

  return errors;
}

/**
 * Extract variable names from template
 */
export function extractVariablesFromTemplate(template: string): string[] {
  const variables: string[] = [];
  const matches = template.matchAll(TEMPLATE_PATTERNS.VARIABLE);

  for (const match of matches) {
    const varName = match[1].trim();
    if (!variables.includes(varName)) {
      variables.push(varName);
    }
  }

  return variables;
}

/**
 * Render template with variables
 */
export function renderTemplate(
  template: string,
  variables: Record<string, any>
): string {
  let rendered = template;

  // Replace variables
  rendered = rendered.replace(TEMPLATE_PATTERNS.VARIABLE, (match, varName) => {
    const name = varName.trim();
    const value = variables[name];

    if (value === undefined) {
      console.warn(`Variable '${name}' not found in context`);
      return match; // Keep placeholder
    }

    return String(value);
  });

  // Handle conditionals
  rendered = rendered.replace(TEMPLATE_PATTERNS.CONDITIONAL, (match, condition, content) => {
    try {
      const conditionResult = evaluateCondition(condition.trim(), variables);
      return conditionResult ? content : '';
    } catch (error) {
      console.error('Error evaluating condition:', error);
      return match;
    }
  });

  // Handle loops
  rendered = rendered.replace(TEMPLATE_PATTERNS.LOOP, (match, itemsVar, content) => {
    const items = variables[itemsVar.trim()];

    if (!Array.isArray(items)) {
      console.warn(`Variable '${itemsVar}' is not an array`);
      return match;
    }

    return items.map(item => {
      return content.replace(/\{\{this\}\}/g, String(item));
    }).join('\n');
  });

  return rendered;
}

/**
 * Evaluate simple condition (safe evaluation)
 */
function evaluateCondition(condition: string, variables: Record<string, any>): boolean {
  try {
    // Simple condition evaluation (only basic comparisons)
    const varName = condition.trim();
    const value = variables[varName];

    // Truthy check
    return Boolean(value);
  } catch (error) {
    console.error('Condition evaluation error:', error);
    return false;
  }
}

/**
 * Validate prompt input against schema
 */
export function validatePromptInput(
  input: Record<string, any>,
  variables: PromptVariable[]
): { valid: boolean; errors: string[] } {
  const errors: string[] = [];

  // Check required variables
  for (const variable of variables) {
    if (variable.required && !(variable.name in input)) {
      errors.push(`Required variable '${variable.name}' is missing`);
      continue;
    }

    const value = input[variable.name];

    // Skip validation if optional and not provided
    if (!variable.required && value === undefined) {
      continue;
    }

    // Type validation
    if (value !== undefined && !validateVariableType(value, variable.type)) {
      errors.push(`Variable '${variable.name}' has invalid type (expected ${variable.type})`);
    }

    // Additional validation
    if (variable.validation) {
      const validationErrors = validateVariableValue(value, variable);
      errors.push(...validationErrors);
    }
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Validate variable type
 */
function validateVariableType(value: any, type: PromptVariableType): boolean {
  switch (type) {
    case 'string':
      return typeof value === 'string';
    case 'number':
      return typeof value === 'number';
    case 'boolean':
      return typeof value === 'boolean';
    case 'array':
      return Array.isArray(value);
    case 'object':
      return typeof value === 'object' && value !== null && !Array.isArray(value);
    default:
      return false;
  }
}

/**
 * Validate variable value against validation rules
 */
function validateVariableValue(value: any, variable: PromptVariable): string[] {
  const errors: string[] = [];
  const validation = variable.validation;

  if (!validation) return errors;

  // String validation
  if (typeof value === 'string') {
    if (validation.minLength && value.length < validation.minLength) {
      errors.push(`${variable.name} must be at least ${validation.minLength} characters`);
    }
    if (validation.maxLength && value.length > validation.maxLength) {
      errors.push(`${variable.name} must be at most ${validation.maxLength} characters`);
    }
    if (validation.pattern) {
      const regex = new RegExp(validation.pattern);
      if (!regex.test(value)) {
        errors.push(validation.message || `${variable.name} does not match required pattern`);
      }
    }
  }

  // Number validation
  if (typeof value === 'number') {
    if (validation.min !== undefined && value < validation.min) {
      errors.push(`${variable.name} must be at least ${validation.min}`);
    }
    if (validation.max !== undefined && value > validation.max) {
      errors.push(`${variable.name} must be at most ${validation.max}`);
    }
    if (validation.integer && !Number.isInteger(value)) {
      errors.push(`${variable.name} must be an integer`);
    }
  }

  // Array validation
  if (Array.isArray(value)) {
    if (validation.minItems && value.length < validation.minItems) {
      errors.push(`${variable.name} must have at least ${validation.minItems} items`);
    }
    if (validation.maxItems && value.length > validation.maxItems) {
      errors.push(`${variable.name} must have at most ${validation.maxItems} items`);
    }
    if (validation.uniqueItems) {
      const unique = new Set(value);
      if (unique.size !== value.length) {
        errors.push(`${variable.name} must have unique items`);
      }
    }
  }

  // Enum validation
  if (validation.enum && !validation.enum.includes(value)) {
    errors.push(`${variable.name} must be one of: ${validation.enum.join(', ')}`);
  }

  return errors;
}

/**
 * Create a new prompt configuration with defaults
 */
export function createPromptConfiguration(
  partial: Partial<PromptConfiguration>
): Omit<PromptConfiguration, 'id' | 'createdAt' | 'updatedAt'> {
  return {
    name: partial.name || '',
    displayName: partial.displayName || '',
    description: partial.description || '',
    category: partial.category || 'general',
    tags: partial.tags || [],
    templateContent: partial.templateContent || '',
    systemPrompt: partial.systemPrompt,
    variables: partial.variables || [],
    inputSchema: partial.inputSchema || {},
    outputSchema: partial.outputSchema || {},
    version: 1,
    status: 'draft',
    createdBy: partial.createdBy || '',
    testCases: partial.testCases || [],
    settings: { ...DEFAULT_PROMPT_SETTINGS, ...partial.settings },
  } as Omit<PromptConfiguration, 'id' | 'createdAt' | 'updatedAt'>;
}
"}

{"file_path": "src/lib/models/tool-config.ts", "initial_content": "/**
 * Tool Configuration Models
 * 
 * Defines TypeScript interfaces for tool registry and configurations
 * stored in Firestore database.
 */

import { Timestamp } from 'firebase/firestore';

/**
 * Tool implementation types
 */
export type ToolType = 'builtin' | 'custom' | 'external';

/**
 * Tool configuration status
 */
export type ToolStatus = 'active' | 'deprecated' | 'disabled';

/**
 * Main tool configuration interface
 */
export interface ToolConfiguration {
  name: string; // Unique identifier
  displayName: string;
  description: string;
  category: string;
  tags: string[];

  // Implementation
  type: ToolType;
  handler: string; // Function name, file path, or URL

  // Schema definitions (Zod schema as JSON)
  inputSchema: Record<string, any>;
  outputSchema: Record<string, any>;

  // Settings
  status: ToolStatus;
  timeout?: number; // milliseconds
  requiresAuth?: boolean;
  cacheable?: boolean;
  cacheTTL?: number; // seconds

  // Metadata
  version: string;
  createdBy: string;
  createdAt: Timestamp;
  updatedAt: Timestamp;

  // Documentation
  examples?: ToolExample[];
  documentation?: string;

  // Advanced settings
  settings?: ToolSettings;
}

/**
 * Example usage of a tool
 */
export interface ToolExample {
  id: string;
  name: string;
  description?: string;
  input: Record<string, any>;
  expectedOutput: any;
  notes?: string;
}

/**
 * Tool execution settings
 */
export interface ToolSettings {
  // Retry configuration
  maxRetries?: number;
  retryDelay?: number; // milliseconds
  retryBackoff?: 'linear' | 'exponential';

  // Rate limiting
  rateLimit?: {
    requestsPerMinute?: number;
    requestsPerHour?: number;
  };

  // Resource limits
  maxMemoryMB?: number;
  maxConcurrent?: number;

  // Error handling
  onError?: 'throw' | 'return-null' | 'return-default';
  defaultOutput?: any;

  // Validation
  validateInput?: boolean;
  validateOutput?: boolean;
  strictMode?: boolean;
}

/**
 * Tool execution context
 */
export interface ToolExecutionContext {
  toolName: string;
  executionId: string;

  // Input
  parameters: Record<string, any>;

  // Metadata
  userId?: string;
  flowId?: string;
  stepId?: string;

  // Settings override
  timeout?: number;
}

/**
 * Tool execution result
 */
export interface ToolExecutionResult {
  executionId: string;
  toolName: string;

  // Output
  output: any;

  // Status
  status: 'success' | 'error';
  error?: {
    message: string;
    code?: string;
    stack?: string;
  };

  // Timing
  startTime: Timestamp;
  endTime: Timestamp;
  duration: number;

  // Metadata
  cached?: boolean;
  retryCount?: number;
}

/**
 * Tool usage statistics
 */
export interface ToolUsageStats {
  toolName: string;
  period: 'hour' | 'day' | 'week' | 'month';
  startDate: Timestamp;
  endDate: Timestamp;

  // Usage metrics
  executionCount: number;
  successCount: number;
  failureCount: number;

  // Performance metrics
  averageDuration: number;
  p95Duration: number;
  p99Duration: number;

  // Cache metrics
  cacheHitRate?: number;

  // Error analysis
  errorsByType?: Record<string, number>;
}

/**
 * Built-in tool metadata
 */
export interface BuiltinToolMetadata {
  name: string;
  displayName: string;
  description: string;
  category: string;

  // Function reference
  handler: Function;

  // Schema
  inputSchema: Record<string, any>;
  outputSchema: Record<string, any>;

  // Examples
  examples?: ToolExample[];
}

/**
 * External tool configuration (API-based)
 */
export interface ExternalToolConfig {
  name: string;
  endpoint: string;
  method: 'GET' | 'POST' | 'PUT' | 'DELETE';

  // Authentication
  authType?: 'none' | 'bearer' | 'api-key' | 'basic';
  authConfig?: {
    token?: string;
    apiKey?: string;
    username?: string;
    password?: string;
  };

  // Headers
  headers?: Record<string, string>;

  // Request mapping
  requestMapping?: {
    bodyPath?: string; // JSON path to put parameters
    queryParams?: Record<string, string>; // Static query params
  };

  // Response mapping
  responseMapping?: {
    dataPath?: string; // JSON path to extract result
    errorPath?: string; // JSON path to extract error
  };
}

/**
 * Tool category definitions
 */
export const TOOL_CATEGORIES = {
  TEXT: 'text',
  DATA: 'data',
  API: 'api',
  UTIL: 'util',
  AI: 'ai',
  SEARCH: 'search',
  FORMAT: 'format',
  VALIDATE: 'validate',
} as const;

/**
 * Firestore collection names
 */
export const TOOL_COLLECTIONS = {
  CONFIGURATIONS: 'toolConfigurations',
  EXECUTIONS: 'toolExecutions',
  STATS: 'toolStats',
} as const;

/**
 * Default tool settings
 */
export const DEFAULT_TOOL_SETTINGS: ToolSettings = {
  maxRetries: 3,
  retryDelay: 1000,
  retryBackoff: 'exponential',
  maxConcurrent: 5,
  onError: 'throw',
  validateInput: true,
  validateOutput: true,
  strictMode: false,
};

/**
 * Validation helpers
 */
export function validateToolConfiguration(config: Partial<ToolConfiguration>): string[] {
  const errors: string[] = [];

  if (!config.name) {
    errors.push('Tool name is required');
  }

  if (!config.displayName) {
    errors.push('Tool display name is required');
  }

  if (!config.type) {
    errors.push('Tool type is required');
  }

  if (!config.handler) {
    errors.push('Tool handler is required');
  }

  if (!config.inputSchema) {
    errors.push('Tool input schema is required');
  }

  if (!config.outputSchema) {
    errors.push('Tool output schema is required');
  }

  // Validate handler based on type
  if (config.type === 'external' && config.handler) {
    try {
      new URL(config.handler);
    } catch {
      errors.push('External tool handler must be a valid URL');
    }
  }

  return errors;
}

/**
 * Create a new tool configuration with defaults
 */
export function createToolConfiguration(
  partial: Partial<ToolConfiguration>
): Omit<ToolConfiguration, 'createdAt' | 'updatedAt'> {
  return {
    name: partial.name || '',
    displayName: partial.displayName || '',
    description: partial.description || '',
    category: partial.category || TOOL_CATEGORIES.UTIL,
    tags: partial.tags || [],
    type: partial.type || 'custom',
    handler: partial.handler || '',
    inputSchema: partial.inputSchema || {},
    outputSchema: partial.outputSchema || {},
    status: 'active',
    timeout: partial.timeout || 30000,
    requiresAuth: partial.requiresAuth ?? false,
    cacheable: partial.cacheable ?? true,
    cacheTTL: partial.cacheTTL || 3600,
    version: partial.version || '1.0.0',
    createdBy: partial.createdBy || '',
    examples: partial.examples || [],
    documentation: partial.documentation,
    settings: { ...DEFAULT_TOOL_SETTINGS, ...partial.settings },
  } as Omit<ToolConfiguration, 'createdAt' | 'updatedAt'>;
}

/**
 * Tool registry interface
 */
export interface ToolRegistry {
  // Register a built-in tool
  registerBuiltin(metadata: BuiltinToolMetadata): void;

  // Register an external tool
  registerExternal(config: ToolConfiguration & { type: 'external' }): void;

  // Get tool by name
  getTool(name: string): ToolConfiguration | null;

  // List all tools
  listTools(filters?: ToolFilters): ToolConfiguration[];

  // Check if tool exists
  hasTool(name: string): boolean;

  // Execute tool
  executeTool(name: string, parameters: Record<string, any>, context?: ToolExecutionContext): Promise<any>;
}

/**
 * Filters for listing tools
 */
export interface ToolFilters {
  category?: string;
  type?: ToolType;
  status?: ToolStatus;
  tags?: string[];
  search?: string;
}

/**
 * Tool error types
 */
export class ToolNotFoundError extends Error {
  constructor(toolName: string) {
    super(`Tool not found: ${toolName}`);
    this.name = 'ToolNotFoundError';
  }
}

export class ToolExecutionError extends Error {
  public readonly toolName: string;
  public readonly cause?: Error;

  constructor(toolName: string, message: string, cause?: Error) {
    super(message);
    this.name = 'ToolExecutionError';
    this.toolName = toolName;
    this.cause = cause;
  }
}

export class ToolTimeoutError extends Error {
  public readonly toolName: string;
  public readonly timeout: number;

  constructor(toolName: string, timeout: number) {
    super(`Tool execution timeout: ${toolName} (${timeout}ms)`);
    this.name = 'ToolTimeoutError';
    this.toolName = toolName;
    this.timeout = timeout;
  }
}

export class ToolValidationError extends Error {
  public readonly toolName: string;
  public readonly validationErrors: string[];

  constructor(toolName: string, errors: string[]) {
    super(`Tool validation failed: ${toolName}\n${errors.join('\n')}`);
    this.name = 'ToolValidationError';
    this.toolName = toolName;
    this.validationErrors = errors;
  }
}

/**
 * Helper to format tool documentation
 */
export function formatToolDocumentation(config: ToolConfiguration): string {
  let doc = `# ${config.displayName}\n\n`;
  doc += `${config.description}\n\n`;

  if (config.category) {
    doc += `**Category:** ${config.category}\n\n`;
  }

  if (config.tags.length > 0) {
    doc += `**Tags:** ${config.tags.join(', ')}\n\n`;
  }

  doc += `## Input Schema\n\`\`\`json\n${JSON.stringify(config.inputSchema, null, 2)}\n\`\`\`\n\n`;
  doc += `## Output Schema\n\`\`\`json\n${JSON.stringify(config.outputSchema, null, 2)}\n\`\`\`\n\n`;

  if (config.examples && config.examples.length > 0) {
    doc += `## Examples\n\n`;
    config.examples.forEach((example, index) => {
      doc += `### Example ${index + 1}: ${example.name}\n\n`;
      if (example.description) {
        doc += `${example.description}\n\n`;
      }
      doc += `**Input:**\n\`\`\`json\n${JSON.stringify(example.input, null, 2)}\n\`\`\`\n\n`;
      doc += `**Output:**\n\`\`\`json\n${JSON.stringify(example.expectedOutput, null, 2)}\n\`\`\`\n\n`;
    });
  }

  if (config.documentation) {
    doc += `## Additional Documentation\n\n${config.documentation}\n\n`;
  }

  return doc;
}
"}

{"file_path": "src/lib/models/execution-trace.ts", "initial_content": "/**
 * Execution Trace Models
 * 
 * Defines TypeScript interfaces for tracking and debugging flow executions.
 */

import { Timestamp } from 'firebase/firestore';

/**
 * Execution status types
 */
export type ExecutionStatus = 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';

/**
 * Step execution status
 */
export type StepStatus = 'pending' | 'running' | 'completed' | 'failed' | 'skipped';

/**
 * Main execution trace interface
 */
export interface ExecutionTrace {
  id: string;
  flowId: string;
  flowName: string;
  flowVersion: number;

  // Execution info
  startTime: Timestamp;
  endTime?: Timestamp;
  duration?: number; // milliseconds
  status: ExecutionStatus;

  // Input/Output
  input: Record<string, any>;
  output?: any;
  error?: ExecutionError;

  // Step traces
  stepTraces: StepTrace[];

  // Metadata
  userId?: string;
  requestId?: string;
  environment: 'development' | 'staging' | 'production';

  // Performance metrics
  metrics?: ExecutionMetrics;
}

/**
 * Individual step trace
 */
export interface StepTrace {
  stepId: string;
  stepName: string;
  stepType: string;
  stepIndex: number;

  // Timing
  startTime: Timestamp;
  endTime?: Timestamp;
  duration?: number;
  status: StepStatus;

  // Input/Output
  input: any;
  output?: any;
  error?: StepError;

  // Additional metadata
  model?: string;
  promptId?: string;
  toolName?: string;

  // Token usage (for LLM steps)
  tokenUsage?: {
    input: number;
    output: number;
    total: number;
  };

  // Context snapshot
  contextBefore?: Record<string, any>;
  contextAfter?: Record<string, any>;

  // Retry information
  retryCount?: number;
  retryErrors?: string[];
}

/**
 * Execution error details
 */
export interface ExecutionError {
  message: string;
  code?: string;
  step?: string;
  stepIndex?: number;
  stack?: string;
  timestamp: Timestamp;
}

/**
 * Step error details
 */
export interface StepError {
  message: string;
  code?: string;
  type?: string;
  recoverable?: boolean;
  stack?: string;
}

/**
 * Execution performance metrics
 */
export interface ExecutionMetrics {
  // Overall
  totalDuration: number;
  stepCount: number;

  // Step breakdown
  stepDurations: Record<string, number>;
  slowestStep?: {
    stepId: string;
    stepName: string;
    duration: number;
  };

  // Token usage (if applicable)
  totalTokens?: {
    input: number;
    output: number;
    total: number;
  };

  // Resource usage
  memoryUsageMB?: number;
  cacheHits?: number;
  cacheMisses?: number;

  // Network
  apiCalls?: number;
  totalApiLatency?: number;
}

/**
 * Execution summary for listing
 */
export interface ExecutionSummary {
  id: string;
  flowName: string;
  status: ExecutionStatus;
  startTime: Timestamp;
  duration?: number;
  userId?: string;
  error?: string;
}

/**
 * Execution filters for querying
 */
export interface ExecutionFilters {
  flowId?: string;
  flowName?: string;
  status?: ExecutionStatus;
  userId?: string;
  startDate?: Date;
  endDate?: Date;
  hasError?: boolean;
  minDuration?: number;
  maxDuration?: number;
}

/**
 * Execution analytics
 */
export interface ExecutionAnalytics {
  flowId: string;
  period: 'hour' | 'day' | 'week' | 'month';
  startDate: Timestamp;
  endDate: Timestamp;

  // Counts
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  cancelledExecutions: number;

  // Performance
  averageDuration: number;
  medianDuration: number;
  p95Duration: number;
  p99Duration: number;

  // Success rate
  successRate: number;

  // Step performance
  stepPerformance?: Record<string, {
    count: number;
    averageDuration: number;
    errorRate: number;
  }>;

  // Error analysis
  errorsByType?: Record<string, number>;
  topErrors?: Array<{
    message: string;
    count: number;
  }>;
}

/**
 * Firestore collection names
 */
export const TRACE_COLLECTIONS = {
  EXECUTIONS: 'executionTraces',
  ANALYTICS: 'executionAnalytics',
} as const;

/**
 * Helper functions
 */

/**
 * Create execution trace
 */
export function createExecutionTrace(
  flowId: string,
  flowName: string,
  flowVersion: number,
  input: Record<string, any>,
  userId?: string,
  requestId?: string
): Omit<ExecutionTrace, 'id'> {
  return {
    flowId,
    flowName,
    flowVersion,
    startTime: Timestamp.now(),
    status: 'pending',
    input,
    stepTraces: [],
    userId,
    requestId,
    environment: process.env.NODE_ENV === 'production' ? 'production' : 'development',
  };
}

/**
 * Create step trace
 */
export function createStepTrace(
  stepId: string,
  stepName: string,
  stepType: string,
  stepIndex: number,
  input: any
): StepTrace {
  return {
    stepId,
    stepName,
    stepType,
    stepIndex,
    startTime: Timestamp.now(),
    status: 'pending',
    input,
  };
}

/**
 * Complete step trace
 */
export function completeStepTrace(
  trace: StepTrace,
  output: any,
  contextAfter?: Record<string, any>
): StepTrace {
  const endTime = Timestamp.now();
  const duration = endTime.toMillis() - trace.startTime.toMillis();

  return {
    ...trace,
    endTime,
    duration,
    status: 'completed',
    output,
    contextAfter,
  };
}

/**
 * Fail step trace
 */
export function failStepTrace(
  trace: StepTrace,
  error: StepError
): StepTrace {
  const endTime = Timestamp.now();
  const duration = endTime.toMillis() - trace.startTime.toMillis();

  return {
    ...trace,
    endTime,
    duration,
    status: 'failed',
    error,
  };
}

/**
 * Complete execution trace
 */
export function completeExecutionTrace(
  trace: ExecutionTrace,
  output: any
): ExecutionTrace {
  const endTime = Timestamp.now();
  const duration = endTime.toMillis() - trace.startTime.toMillis();

  return {
    ...trace,
    endTime,
    duration,
    status: 'completed',
    output,
    metrics: calculateMetrics(trace, duration),
  };
}

/**
 * Fail execution trace
 */
export function failExecutionTrace(
  trace: ExecutionTrace,
  error: ExecutionError
): ExecutionTrace {
  const endTime = Timestamp.now();
  const duration = endTime.toMillis() - trace.startTime.toMillis();

  return {
    ...trace,
    endTime,
    duration,
    status: 'failed',
    error,
    metrics: calculateMetrics(trace, duration),
  };
}

/**
 * Calculate execution metrics
 */
function calculateMetrics(
  trace: ExecutionTrace,
  totalDuration: number
): ExecutionMetrics {
  const stepDurations: Record<string, number> = {};
  let slowestStep: ExecutionMetrics['slowestStep'];
  let maxDuration = 0;

  const totalTokens = {
    input: 0,
    output: 0,
    total: 0,
  };

  for (const step of trace.stepTraces) {
    if (step.duration) {
      stepDurations[step.stepId] = step.duration;

      if (step.duration > maxDuration) {
        maxDuration = step.duration;
        slowestStep = {
          stepId: step.stepId,
          stepName: step.stepName,
          duration: step.duration,
        };
      }
    }

    if (step.tokenUsage) {
      totalTokens.input += step.tokenUsage.input;
      totalTokens.output += step.tokenUsage.output;
      totalTokens.total += step.tokenUsage.total;
    }
  }

  return {
    totalDuration,
    stepCount: trace.stepTraces.length,
    stepDurations,
    slowestStep,
    totalTokens: totalTokens.total > 0 ? totalTokens : undefined,
  };
}

/**
 * Format execution trace for display
 */
export function formatExecutionTrace(trace: ExecutionTrace): string {
  let output = `Execution Trace: ${trace.id}\n`;
  output += `Flow: ${trace.flowName} (v${trace.flowVersion})\n`;
  output += `Status: ${trace.status}\n`;
  output += `Duration: ${trace.duration ? `${trace.duration}ms` : 'N/A'}\n`;
  output += `\n`;

  if (trace.error) {
    output += `Error: ${trace.error.message}\n`;
    if (trace.error.step) {
      output += `Failed at step: ${trace.error.step}\n`;
    }
    output += `\n`;
  }

  output += `Steps:\n`;
  trace.stepTraces.forEach((step, index) => {
    output += `  ${index + 1}. ${step.stepName} (${step.stepType})\n`;
    output += `     Status: ${step.status}\n`;
    output += `     Duration: ${step.duration ? `${step.duration}ms` : 'N/A'}\n`;

    if (step.error) {
      output += `     Error: ${step.error.message}\n`;
    }

    if (step.tokenUsage) {
      output += `     Tokens: ${step.tokenUsage.input} in, ${step.tokenUsage.output} out\n`;
    }

    output += `\n`;
  });

  if (trace.metrics) {
    output += `Metrics:\n`;
    output += `  Total Duration: ${trace.metrics.totalDuration}ms\n`;
    output += `  Step Count: ${trace.metrics.stepCount}\n`;

    if (trace.metrics.slowestStep) {
      output += `  Slowest Step: ${trace.metrics.slowestStep.stepName} (${trace.metrics.slowestStep.duration}ms)\n`;
    }

    if (trace.metrics.totalTokens) {
      output += `  Total Tokens: ${trace.metrics.totalTokens.total}\n`;
    }
  }

  return output;
}

/**
 * Get execution summary from trace
 */
export function getExecutionSummary(trace: ExecutionTrace): ExecutionSummary {
  return {
    id: trace.id,
    flowName: trace.flowName,
    status: trace.status,
    startTime: trace.startTime,
    duration: trace.duration,
    userId: trace.userId,
    error: trace.error?.message,
  };
}
"}

{"file_path": "src/ai/dynamic-flow/context-manager.ts", "initial_content": "/**
 * Context Manager
 * 
 * Manages data flow and variable context between flow steps.
 * Handles variable storage, retrieval, and template resolution.
 */

/**
 * Context Manager for managing step-to-step data flow
 */
export class ContextManager {
  private variables: Map<string, any> = new Map();
  private history: Array<{ stepId: string; stepName: string; data: any; timestamp: number }> = [];
  private readonly initialData: Record<string, any>;

  constructor(initialData: Record<string, any> = {}) {
    this.initialData = { ...initialData };

    // Initialize with input data
    for (const [key, value] of Object.entries(initialData)) {
      this.variables.set(key, value);
    }
  }

  /**
   * Update context from step output
   */
  updateFromStep(
    stepId: string,
    stepName: string,
    output: any,
    mapping?: Record<string, string>
  ): void {
    // Store in history
    this.history.push({
      stepId,
      stepName,
      data: output,
      timestamp: Date.now(),
    });

    if (mapping) {
      // Use custom mapping to extract data from output
      for (const [targetVar, sourceExpression] of Object.entries(mapping)) {
        const value = this.resolveExpression(sourceExpression, output);
        this.variables.set(targetVar, value);
      }
    } else {
      // Default behavior: merge output into context
      if (typeof output === 'object' && output !== null && !Array.isArray(output)) {
        // Merge object properties into context
        for (const [key, value] of Object.entries(output)) {
          this.variables.set(key, value);
        }
      } else {
        // Store primitive or array as 'lastResult'
        this.variables.set('lastResult', output);
      }
    }

    // Always store the raw step output with stepId prefix
    this.variables.set(`step_${stepId}_output`, output);
  }

  /**
   * Get variable value
   */
  get(key: string): any {
    return this.variables.get(key);
  }

  /**
   * Set variable value
   */
  set(key: string, value: any): void {
    this.variables.set(key, value);
  }

  /**
   * Check if variable exists
   */
  has(key: string): boolean {
    return this.variables.has(key);
  }

  /**
   * Delete variable
   */
  delete(key: string): boolean {
    return this.variables.delete(key);
  }

  /**
   * Get all variables as an object
   */
  getAllVariables(): Record<string, any> {
    return Object.fromEntries(this.variables);
  }

  /**
   * Get initial input data
   */
  getInitialData(): Record<string, any> {
    return { ...this.initialData };
  }

  /**
   * Resolve template string with variables
   * Supports {{variable}} syntax
   */
  resolve(template: string): string {
    if (typeof template !== 'string') {
      return String(template);
    }

    return template.replace(/\{\{([^}]+)\}\}/g, (match, expression) => {
      const trimmed = expression.trim();

      // Handle nested property access: {{object.property}}
      if (trimmed.includes('.')) {
        const value = this.resolveExpression(trimmed);
        return value !== undefined ? String(value) : match;
      }

      // Simple variable lookup
      const value = this.get(trimmed);
      return value !== undefined ? String(value) : match;
    });
  }

  /**
   * Resolve expression from context (supports nested properties)
   * Example: "user.name" or "items[0].title"
   */
  resolveExpression(expression: string, data?: any): any {
    const source = data || this.getAllVariables();

    // Split by dots for nested property access
    const parts = expression.split('.');
    let current: any = source;

    for (const part of parts) {
      // Handle array indexing: items[0]
      const arrayMatch = part.match(/^(\w+)\[(\d+)\]$/);

      if (arrayMatch) {
        const [, arrayName, index] = arrayMatch;
        current = current?.[arrayName]?.[parseInt(index, 10)];
      } else {
        current = current?.[part];
      }

      if (current === undefined) {
        return undefined;
      }
    }

    return current;
  }

  /**
   * Get execution history
   */
  getHistory(): Array<{ stepId: string; stepName: string; data: any; timestamp: number }> {
    return [...this.history];
  }

  /**
   * Get history for specific step
   */
  getStepHistory(stepId: string): any | undefined {
    const entry = this.history.find(h => h.stepId === stepId);
    return entry?.data;
  }

  /**
   * Get final output from context
   * Attempts to extract meaningful output based on conventions
   */
  getFinalOutput(): Record<string, any> {
    const output: Record<string, any> = {};

    // Get all non-internal variables
    for (const [key, value] of this.variables.entries()) {
      // Skip step-specific outputs (internal bookkeeping)
      if (!key.startsWith('step_')) {
        output[key] = value;
      }
    }

    return output;
  }

  /**
   * Create a snapshot of current context state
   */
  snapshot(): Record<string, any> {
    return {
      variables: this.getAllVariables(),
      history: this.getHistory(),
      timestamp: Date.now(),
    };
  }

  /**
   * Restore context from snapshot
   */
  restore(snapshot: { variables: Record<string, any>; history: any[] }): void {
    this.variables.clear();

    for (const [key, value] of Object.entries(snapshot.variables)) {
      this.variables.set(key, value);
    }

    this.history = snapshot.history || [];
  }

  /**
   * Clear all variables (except initial data)
   */
  clear(): void {
    this.variables.clear();
    this.history = [];

    // Restore initial data
    for (const [key, value] of Object.entries(this.initialData)) {
      this.variables.set(key, value);
    }
  }

  /**
   * Clone the context manager
   */
  clone(): ContextManager {
    const cloned = new ContextManager(this.initialData);

    for (const [key, value] of this.variables.entries()) {
      cloned.set(key, this.deepClone(value));
    }

    cloned.history = this.history.map(h => ({ ...h, data: this.deepClone(h.data) }));

    return cloned;
  }

  /**
   * Deep clone a value
   */
  private deepClone(value: any): any {
    if (value === null || value === undefined) {
      return value;
    }

    if (typeof value !== 'object') {
      return value;
    }

    if (Array.isArray(value)) {
      return value.map(item => this.deepClone(item));
    }

    if (value instanceof Date) {
      return new Date(value);
    }

    if (value instanceof Map) {
      const cloned = new Map();
      value.forEach((v, k) => cloned.set(k, this.deepClone(v)));
      return cloned;
    }

    if (value instanceof Set) {
      return new Set(Array.from(value).map(item => this.deepClone(item)));
    }

    // Plain object
    const cloned: any = {};
    for (const [key, val] of Object.entries(value)) {
      cloned[key] = this.deepClone(val);
    }
    return cloned;
  }

  /**
   * Merge another context into this one
   */
  merge(other: ContextManager): void {
    for (const [key, value] of other.variables.entries()) {
      this.variables.set(key, value);
    }

    this.history.push(...other.history);
  }

  /**
   * Get context size (for debugging/monitoring)
   */
  getSize(): { variableCount: number; historySize: number; approximateSizeKB: number } {
    const json = JSON.stringify(this.getAllVariables());
    const approximateSizeKB = new TextEncoder().encode(json).length / 1024;

    return {
      variableCount: this.variables.size,
      historySize: this.history.length,
      approximateSizeKB: Math.round(approximateSizeKB * 100) / 100,
    };
  }

  /**
   * Debug: Print context state
   */
  debug(): string {
    const vars = this.getAllVariables();
    const size = this.getSize();

    let output = '=== Context Manager Debug ===\n';
    output += `Variables: ${size.variableCount}\n`;
    output += `History: ${size.historySize} entries\n`;
    output += `Size: ${size.approximateSizeKB} KB\n\n`;

    output += 'Variables:\n';
    for (const [key, value] of Object.entries(vars)) {
      const valueStr = typeof value === 'object' 
        ? JSON.stringify(value).substring(0, 100) + '...'
        : String(value);
      output += `  ${key}: ${valueStr}\n`;
    }

    output += '\nHistory:\n';
    this.history.forEach((entry, index) => {
      output += `  ${index + 1}. ${entry.stepName} (${entry.stepId})\n`;
    });

    return output;
  }

  /**
   * Evaluate a simple condition expression
   * Returns true/false based on context variables
   */
  evaluateCondition(condition: string): boolean {
    try {
      // Get all variables for evaluation
      const vars = this.getAllVariables();

      // Create a safe evaluation context
      // Only allow basic comparisons, no function calls
      const safeCondition = condition
        .replace(/[^a-zA-Z0-9._\s<>=!&|()]/g, '') // Remove dangerous characters
        .trim();

      // Simple variable existence check
      if (!safeCondition.includes(' ')) {
        const value = this.resolveExpression(safeCondition);
        return Boolean(value);
      }

      // For complex conditions, use Function constructor with limited scope
      const varNames = Object.keys(vars);
      const varValues = Object.values(vars);

      try {
        const func = new Function(...varNames, `return (${safeCondition});`);
        return Boolean(func(...varValues));
      } catch {
        console.warn(`Failed to evaluate condition: ${condition}`);
        return false;
      }
    } catch (error) {
      console.error('Condition evaluation error:', error);
      return false;
    }
  }
}

/**
 * Create a context manager with initial data
 */
export function createContextManager(initialData: Record<string, any> = {}): ContextManager {
  return new ContextManager(initialData);
}
"}

{"file_path": "src/ai/dynamic-flow/schema-validator.ts", "initial_content": "/**
 * Schema Validator
 * 
 * Validates data against schemas defined in flow configurations.
 * Supports dynamic Zod schema generation from JSON schema definitions.
 */

import { z, ZodSchema, ZodType, ZodTypeAny } from 'zod';

/**
 * JSON schema type definitions
 */
interface JsonSchema {
  type: 'string' | 'number' | 'boolean' | 'array' | 'object' | 'any';
  description?: string;
  optional?: boolean;
  nullable?: boolean;
  default?: any;

  // String constraints
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  email?: boolean;
  url?: boolean;
  uuid?: boolean;

  // Number constraints
  min?: number;
  max?: number;
  int?: boolean;
  positive?: boolean;
  negative?: boolean;

  // Array constraints
  items?: JsonSchema;
  minItems?: number;
  maxItems?: number;

  // Object constraints
  properties?: Record<string, JsonSchema>;
  required?: string[];
  additionalProperties?: boolean;

  // Enum
  enum?: any[];
}

/**
 * Validation result
 */
export interface ValidationResult {
  success: boolean;
  data?: any;
  errors?: ValidationError[];
}

/**
 * Validation error
 */
export interface ValidationError {
  path: string[];
  message: string;
  code?: string;
}

/**
 * Schema Validator class
 */
export class SchemaValidator {
  /**
   * Validate data against a JSON schema
   */
  validate(data: any, schemaDefinition: Record<string, any>): ValidationResult {
    try {
      // Convert JSON schema to Zod schema
      const zodSchema = this.jsonSchemaToZod(schemaDefinition);

      // Validate data
      const result = zodSchema.safeParse(data);

      if (result.success) {
        return {
          success: true,
          data: result.data,
        };
      } else {
        return {
          success: false,
          errors: this.formatZodErrors(result.error),
        };
      }
    } catch (error) {
      return {
        success: false,
        errors: [{
          path: [],
          message: error instanceof Error ? error.message : 'Unknown validation error',
        }],
      };
    }
  }

  /**
   * Convert JSON schema to Zod schema
   */
  private jsonSchemaToZod(schema: JsonSchema | Record<string, any>): ZodTypeAny {
    // Handle empty schema
    if (!schema || Object.keys(schema).length === 0) {
      return z.any();
    }

    // If schema has 'type' property, treat as single type schema
    if ('type' in schema) {
      return this.buildZodType(schema as JsonSchema);
    }

    // Otherwise, treat as object schema with properties
    if ('properties' in schema || typeof schema === 'object') {
      return this.buildObjectSchema(schema);
    }

    return z.any();
  }

  /**
   * Build Zod type from JSON schema
   */
  private buildZodType(schema: JsonSchema): ZodTypeAny {
    let zodType: ZodTypeAny;

    // Base type
    switch (schema.type) {
      case 'string':
        zodType = this.buildStringSchema(schema);
        break;
      case 'number':
        zodType = this.buildNumberSchema(schema);
        break;
      case 'boolean':
        zodType = z.boolean();
        break;
      case 'array':
        zodType = this.buildArraySchema(schema);
        break;
      case 'object':
        zodType = this.buildObjectSchema(schema);
        break;
      case 'any':
      default:
        zodType = z.any();
    }

    // Apply modifiers
    if (schema.optional) {
      zodType = zodType.optional();
    }

    if (schema.nullable) {
      zodType = zodType.nullable();
    }

    if (schema.default !== undefined) {
      zodType = zodType.default(schema.default);
    }

    if (schema.description) {
      zodType = zodType.describe(schema.description);
    }

    return zodType;
  }

  /**
   * Build string schema
   */
  private buildStringSchema(schema: JsonSchema): ZodType {
    let stringSchema = z.string();

    if (schema.minLength !== undefined) {
      stringSchema = stringSchema.min(schema.minLength);
    }

    if (schema.maxLength !== undefined) {
      stringSchema = stringSchema.max(schema.maxLength);
    }

    if (schema.pattern) {
      stringSchema = stringSchema.regex(new RegExp(schema.pattern));
    }

    if (schema.email) {
      stringSchema = stringSchema.email();
    }

    if (schema.url) {
      stringSchema = stringSchema.url();
    }

    if (schema.uuid) {
      stringSchema = stringSchema.uuid();
    }

    if (schema.enum) {
      return z.enum(schema.enum as [string, ...string[]]);
    }

    return stringSchema;
  }

  /**
   * Build number schema
   */
  private buildNumberSchema(schema: JsonSchema): ZodType {
    let numberSchema = schema.int ? z.number().int() : z.number();

    if (schema.min !== undefined) {
      numberSchema = numberSchema.min(schema.min);
    }

    if (schema.max !== undefined) {
      numberSchema = numberSchema.max(schema.max);
    }

    if (schema.positive) {
      numberSchema = numberSchema.positive();
    }

    if (schema.negative) {
      numberSchema = numberSchema.negative();
    }

    if (schema.enum) {
      return z.enum(schema.enum as [string, ...string[]]);
    }

    return numberSchema;
  }

  /**
   * Build array schema
   */
  private buildArraySchema(schema: JsonSchema): ZodType {
    let itemSchema: ZodTypeAny = z.any();

    if (schema.items) {
      itemSchema = this.buildZodType(schema.items);
    }

    let arraySchema = z.array(itemSchema);

    if (schema.minItems !== undefined) {
      arraySchema = arraySchema.min(schema.minItems);
    }

    if (schema.maxItems !== undefined) {
      arraySchema = arraySchema.max(schema.maxItems);
    }

    return arraySchema;
  }

  /**
   * Build object schema
   */
  private buildObjectSchema(schema: Record<string, any>): ZodType {
    const shape: Record<string, ZodTypeAny> = {};

    const properties = schema.properties || schema;
    const required = schema.required || [];

    for (const [key, propSchema] of Object.entries(properties)) {
      if (typeof propSchema === 'object' && propSchema !== null) {
        // Mark as optional if not in required array
        const isRequired = required.includes(key);
        const prop = propSchema as JsonSchema;

        if (!isRequired && !prop.optional) {
          prop.optional = true;
        }

        shape[key] = this.buildZodType(prop);
      } else {
        shape[key] = z.any();
      }
    }

    let objectSchema = z.object(shape);

    // Handle additional properties
    if (schema.additionalProperties === false) {
      objectSchema = objectSchema.strict();
    }

    return objectSchema;
  }

  /**
   * Format Zod errors to standard format
   */
  private formatZodErrors(zodError: z.ZodError): ValidationError[] {
    return zodError.errors.map(error => ({
      path: error.path.map(p => String(p)),
      message: error.message,
      code: error.code,
    }));
  }

  /**
   * Validate and transform data
   */
  validateAndTransform(data: any, schemaDefinition: Record<string, any>): any {
    const result = this.validate(data, schemaDefinition);

    if (!result.success) {
      const errorMessages = result.errors?.map(e => 
        `${e.path.join('.')}: ${e.message}`
      ).join(', ');

      throw new ValidationError(
        `Validation failed: ${errorMessages}`,
        result.errors || []
      );
    }

    return result.data;
  }

  /**
   * Validate input for a step
   */
  validateStepInput(
    input: any,
    stepSchema: Record<string, any>,
    stepName: string
  ): any {
    try {
      return this.validateAndTransform(input, stepSchema);
    } catch (error) {
      if (error instanceof ValidationError) {
        throw new StepValidationError(stepName, 'input', error.errors);
      }
      throw error;
    }
  }

  /**
   * Validate output from a step
   */
  validateStepOutput(
    output: any,
    stepSchema: Record<string, any>,
    stepName: string
  ): any {
    try {
      return this.validateAndTransform(output, stepSchema);
    } catch (error) {
      if (error instanceof ValidationError) {
        throw new StepValidationError(stepName, 'output', error.errors);
      }
      throw error;
    }
  }
}

/**
 * Custom error classes
 */
export class ValidationError extends Error {
  public readonly errors: ValidationError[];

  constructor(message: string, errors: ValidationError[]) {
    super(message);
    this.name = 'ValidationError';
    this.errors = errors;
  }
}

export class StepValidationError extends Error {
  public readonly stepName: string;
  public readonly validationType: 'input' | 'output';
  public readonly errors: ValidationError[];

  constructor(stepName: string, validationType: 'input' | 'output', errors: ValidationError[]) {
    const errorMessages = errors.map(e => `${e.path.join('.')}: ${e.message}`).join(', ');
    super(`Step "${stepName}" ${validationType} validation failed: ${errorMessages}`);
    this.name = 'StepValidationError';
    this.stepName = stepName;
    this.validationType = validationType;
    this.errors = errors;
  }
}

/**
 * Singleton instance
 */
export const schemaValidator = new SchemaValidator();

/**
 * Convenience function to validate data
 */
export function validateSchema(data: any, schema: Record<string, any>): any {
  return schemaValidator.validateAndTransform(data, schema);
}

/**
 * Check if data matches schema without throwing
 */
export function isValidSchema(data: any, schema: Record<string, any>): boolean {
  const result = schemaValidator.validate(data, schema);
  return result.success;
}

/**
 * Get validation errors without throwing
 */
export function getValidationErrors(
  data: any,
  schema: Record<string, any>
): ValidationError[] {
  const result = schemaValidator.validate(data, schema);
  return result.errors || [];
}

/**
 * Create a reusable validator function
 */
export function createValidator(schema: Record<string, any>): (data: any) => any {
  return (data: any) => validateSchema(data, schema);
}

/**
 * Merge multiple schemas
 */
export function mergeSchemas(...schemas: Record<string, any>[]): Record<string, any> {
  const merged: Record<string, any> = {
    type: 'object',
    properties: {},
    required: [],
  };

  for (const schema of schemas) {
    if (schema.properties) {
      merged.properties = { ...merged.properties, ...schema.properties };
    }

    if (schema.required) {
      merged.required = [...new Set([...merged.required, ...schema.required])];
    }
  }

  return merged;
}

/**
 * Helper to create common schemas
 */
export const CommonSchemas = {
  string: (opts?: { min?: number; max?: number; pattern?: string }): JsonSchema => ({
    type: 'string',
    minLength: opts?.min,
    maxLength: opts?.max,
    pattern: opts?.pattern,
  }),

  number: (opts?: { min?: number; max?: number; int?: boolean }): JsonSchema => ({
    type: 'number',
    min: opts?.min,
    max: opts?.max,
    int: opts?.int,
  }),

  boolean: (): JsonSchema => ({
    type: 'boolean',
  }),

  array: (items?: JsonSchema, opts?: { min?: number; max?: number }): JsonSchema => ({
    type: 'array',
    items: items || { type: 'any' },
    minItems: opts?.min,
    maxItems: opts?.max,
  }),

  object: (properties: Record<string, JsonSchema>, required?: string[]): JsonSchema => ({
    type: 'object',
    properties,
    required,
  }),

  email: (): JsonSchema => ({
    type: 'string',
    email: true,
  }),

  url: (): JsonSchema => ({
    type: 'string',
    url: true,
  }),

  enum: (values: string[]): JsonSchema => ({
    type: 'string',
    enum: values,
  }),

  optional: (schema: JsonSchema): JsonSchema => ({
    ...schema,
    optional: true,
  }),

  nullable: (schema: JsonSchema): JsonSchema => ({
    ...schema,
    nullable: true,
  }),
};
"}

{"file_path": "src/ai/flows/dynamic-flow-executor.ts", "initial_content": "/**
 * Dynamic Flow Executor
 * 
 * Executes flows based on database configurations rather than hardcoded logic.
 * This is the core runtime engine for the dynamic flow system.
 */

'use server';

import { ai } from '@/ai/genkit';
import { z } from 'zod';
import { ContextManager } from '@/ai/dynamic-flow/context-manager';
import { schemaValidator } from '@/ai/dynamic-flow/schema-validator';
import { FlowConfiguration, FlowStep } from '@/lib/models/flow-config';
import { 
  ExecutionTrace, 
  StepTrace, 
  createExecutionTrace, 
  createStepTrace,
  completeStepTrace,
  failStepTrace,
  completeExecutionTrace,
  failExecutionTrace,
} from '@/lib/models/execution-trace';
import { Timestamp } from 'firebase/firestore';

/**
 * Input schema for dynamic flow executor
 */
const DynamicFlowInputSchema = z.object({
  flowName: z.string().describe('Name of the flow to execute'),
  payload: z.record(z.any()).describe('Input data for the flow'),
  userId: z.string().optional().describe('ID of the user executing the flow'),
  requestId: z.string().optional().describe('Request ID for tracking'),
  enableTracing: z.boolean().optional().default(true).describe('Enable execution tracing'),
});

/**
 * Output schema for dynamic flow executor
 */
const DynamicFlowOutputSchema = z.object({
  success: z.boolean(),
  output: z.any().optional(),
  error: z.string().optional(),
  executionId: z.string().optional(),
  traceId: z.string().optional(),
  duration: z.number().optional(),
});

/**
 * Dynamic Flow Executor
 * 
 * Main entry point for executing configuration-driven flows
 */
export const dynamicFlowExecutor = ai.defineFlow(
  {
    name: 'DynamicFlowExecutor',
    inputSchema: DynamicFlowInputSchema,
    outputSchema: DynamicFlowOutputSchema,
  },
  async (input) => {
    const startTime = Date.now();
    const executionId = generateExecutionId();

    try {
      // 1. Load flow configuration from database
      const flowConfig = await loadFlowConfiguration(input.flowName);

      if (!flowConfig) {
        throw new FlowNotFoundError(input.flowName);
      }

      if (flowConfig.status !== 'active') {
        throw new FlowNotActiveError(input.flowName, flowConfig.status);
      }

      // 2. Create execution trace
      let trace: ExecutionTrace | null = null;
      if (input.enableTracing) {
        trace = createExecutionTrace(
          flowConfig.id,
          flowConfig.name,
          flowConfig.version,
          input.payload,
          input.userId,
          input.requestId
        ) as ExecutionTrace;
        trace.id = executionId;
      }

      // 3. Validate input against flow schema
      const validatedInput = schemaValidator.validateAndTransform(
        input.payload,
        flowConfig.inputSchema
      );

      // 4. Initialize context manager
      const context = new ContextManager(validatedInput);

      // 5. Execute steps sequentially
      for (let i = 0; i < flowConfig.steps.length; i++) {
        const step = flowConfig.steps[i];

        // Create step trace
        let stepTrace: StepTrace | null = null;
        if (trace) {
          stepTrace = createStepTrace(
            step.id,
            step.name,
            step.type,
            i,
            context.snapshot().variables
          );
          stepTrace.status = 'running';
          trace.stepTraces.push(stepTrace);
        }

        try {
          // Check condition if exists
          if (step.condition && !context.evaluateCondition(step.condition)) {
            console.log(`Skipping step ${step.name}: condition not met`);
            if (stepTrace) {
              stepTrace.status = 'skipped';
              stepTrace.endTime = Timestamp.now();
            }
            continue;
          }

          // Map inputs from context
          const stepInput = mapInputsFromContext(step, context);

          // Validate step input
          const validatedStepInput = schemaValidator.validateStepInput(
            stepInput,
            step.inputSchema,
            step.name
          );

          if (stepTrace) {
            stepTrace.input = validatedStepInput;
          }

          // Execute step (placeholder - will implement in next file)
          const stepOutput = await executeStep(step, validatedStepInput, context);

          // Validate step output
          const validatedStepOutput = schemaValidator.validateStepOutput(
            stepOutput,
            step.outputSchema,
            step.name
          );

          // Update context
          context.updateFromStep(step.id, step.name, validatedStepOutput, step.outputMapping);

          // Complete step trace
          if (stepTrace) {
            completeStepTrace(stepTrace, validatedStepOutput, context.snapshot().variables);
          }

        } catch (error) {
          // Handle step error
          console.error(`Step ${step.name} failed:`, error);

          if (stepTrace) {
            failStepTrace(stepTrace, {
              message: error instanceof Error ? error.message : 'Unknown error',
              type: error instanceof Error ? error.constructor.name : 'UnknownError',
              recoverable: step.onError !== 'stop',
            });
          }

          const handled = await handleStepError(error, step, context, flowConfig);

          if (!handled) {
            throw new StepExecutionError(step.name, error);
          }
        }
      }

      // 6. Extract final output
      const output = context.getFinalOutput();

      // 7. Validate output against flow schema
      const validatedOutput = schemaValidator.validateAndTransform(
        output,
        flowConfig.outputSchema
      );

      // 8. Complete execution trace
      const duration = Date.now() - startTime;

      if (trace) {
        completeExecutionTrace(trace, validatedOutput);
        // TODO: Save trace to database
      }

      return {
        success: true,
        output: validatedOutput,
        executionId,
        traceId: trace?.id,
        duration,
      };

    } catch (error) {
      console.error('Flow execution failed:', error);

      const duration = Date.now() - startTime;

      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error',
        executionId,
        duration,
      };
    }
  }
);

/**
 * Load flow configuration from database
 * TODO: Implement actual database loading
 */
async function loadFlowConfiguration(flowName: string): Promise<FlowConfiguration | null> {
  // Placeholder implementation
  // In the real implementation, this will query Firestore
  console.warn('loadFlowConfiguration is a placeholder - implement database query');
  return null;
}

/**
 * Execute a single step
 * TODO: Implement actual step execution
 */
async function executeStep(
  step: FlowStep,
  input: Record<string, any>,
  context: ContextManager
): Promise<any> {
  // Placeholder implementation
  // Will be implemented in step-executor.ts
  console.warn('executeStep is a placeholder - implement step handlers');
  throw new Error('Step execution not yet implemented');
}

/**
 * Map inputs from context based on step's input mapping
 */
function mapInputsFromContext(
  step: FlowStep,
  context: ContextManager
): Record<string, any> {
  if (!step.inputMapping) {
    // No mapping - pass all context variables
    return context.getAllVariables();
  }

  const result: Record<string, any> = {};

  for (const [targetKey, sourceExpression] of Object.entries(step.inputMapping)) {
    const value = context.resolveExpression(sourceExpression);
    result[targetKey] = value;
  }

  return result;
}

/**
 * Handle step execution error based on error handling strategy
 */
async function handleStepError(
  error: Error,
  step: FlowStep,
  context: ContextManager,
  flowConfig: FlowConfiguration
): Promise<boolean> {
  switch (step.onError) {
    case 'skip':
      console.warn(`Step ${step.id} failed, skipping:`, error.message);
      return true; // Error handled, continue execution

    case 'retry':
      const retryCount = step.retryCount || 3;
      console.log(`Step ${step.id} will be retried (max ${retryCount} attempts)`);
      // TODO: Implement retry logic
      return false; // Not handled yet

    case 'stop':
    default:
      return false; // Not handled, will throw
  }
}

/**
 * Generate unique execution ID
 */
function generateExecutionId(): string {
  return `exec_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Custom error classes
 */
export class FlowNotFoundError extends Error {
  constructor(flowName: string) {
    super(`Flow not found: ${flowName}`);
    this.name = 'FlowNotFoundError';
  }
}

export class FlowNotActiveError extends Error {
  constructor(flowName: string, status: string) {
    super(`Flow is not active: ${flowName} (status: ${status})`);
    this.name = 'FlowNotActiveError';
  }
}

export class StepExecutionError extends Error {
  public readonly stepName: string;
  public readonly cause?: Error;

  constructor(stepName: string, cause: Error) {
    super(`Step execution failed: ${stepName} - ${cause.message}`);
    this.name = 'StepExecutionError';
    this.stepName = stepName;
    this.cause = cause;
  }
}

export class FlowTimeoutError extends Error {
  constructor(flowName: string, timeout: number) {
    super(`Flow execution timeout: ${flowName} (${timeout}ms)`);
    this.name = 'FlowTimeoutError';
  }
}

/**
 * Export for use in other modules
 */
export { DynamicFlowInputSchema, DynamicFlowOutputSchema };
"}

{"file_path": "src/services/flow-config-service.ts", "initial_content": "/**
 * Flow Configuration Service
 * 
 * CRUD operations for flow configurations stored in Firestore.
 * Handles flow creation, updates, versioning, and retrieval.
 */

import { 
  collection, 
  doc, 
  getDoc, 
  getDocs, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy, 
  limit,
  Timestamp,
  QueryConstraint,
} from 'firebase/firestore';
import { db } from '@/lib/firebase/client-init';
import { 
  FlowConfiguration, 
  FlowVersion, 
  FlowStatus,
  FLOW_COLLECTIONS,
  validateFlowConfiguration,
  createFlowConfiguration,
} from '@/lib/models/flow-config';

/**
 * Flow Configuration Service Class
 */
export class FlowConfigService {
  private readonly flowsCollection = collection(db, FLOW_COLLECTIONS.CONFIGURATIONS);
  private readonly versionsCollection = collection(db, FLOW_COLLECTIONS.VERSIONS);

  /**
   * Get flow configuration by name
   */
  async getFlowByName(flowName: string): Promise<FlowConfiguration | null> {
    try {
      const q = query(
        this.flowsCollection,
        where('name', '==', flowName),
        where('status', '==', 'active'),
        limit(1)
      );

      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        return null;
      }

      const docData = snapshot.docs[0].data();
      return this.mapToFlowConfiguration(snapshot.docs[0].id, docData);
    } catch (error) {
      console.error('Error getting flow by name:', error);
      throw new FlowServiceError('Failed to get flow by name', error);
    }
  }

  /**
   * Get flow configuration by ID
   */
  async getFlowById(flowId: string): Promise<FlowConfiguration | null> {
    try {
      const docRef = doc(this.flowsCollection, flowId);
      const docSnap = await getDoc(docRef);

      if (!docSnap.exists()) {
        return null;
      }

      return this.mapToFlowConfiguration(docSnap.id, docSnap.data());
    } catch (error) {
      console.error('Error getting flow by ID:', error);
      throw new FlowServiceError('Failed to get flow by ID', error);
    }
  }

  /**
   * List all flows with optional filters
   */
  async listFlows(filters?: FlowFilters): Promise<FlowConfiguration[]> {
    try {
      const constraints: QueryConstraint[] = [];

      if (filters?.status) {
        constraints.push(where('status', '==', filters.status));
      }

      if (filters?.category) {
        constraints.push(where('category', '==', filters.category));
      }

      if (filters?.tags && filters.tags.length > 0) {
        constraints.push(where('tags', 'array-contains-any', filters.tags));
      }

      // Order by creation date (most recent first)
      constraints.push(orderBy('createdAt', 'desc'));

      if (filters?.limit) {
        constraints.push(limit(filters.limit));
      }

      const q = query(this.flowsCollection, ...constraints);
      const snapshot = await getDocs(q);

      return snapshot.docs.map(doc => 
        this.mapToFlowConfiguration(doc.id, doc.data())
      );
    } catch (error) {
      console.error('Error listing flows:', error);
      throw new FlowServiceError('Failed to list flows', error);
    }
  }

  /**
   * Create a new flow configuration
   */
  async createFlow(
    flow: Partial<FlowConfiguration>,
    userId: string
  ): Promise<FlowConfiguration> {
    try {
      // Validate flow configuration
      const errors = validateFlowConfiguration(flow);
      if (errors.length > 0) {
        throw new ValidationError('Flow validation failed', errors);
      }

      // Check if flow with same name already exists
      const existing = await this.getFlowByName(flow.name!);
      if (existing) {
        throw new FlowAlreadyExistsError(flow.name!);
      }

      // Create flow configuration with defaults
      const flowConfig = createFlowConfiguration({
        ...flow,
        createdBy: userId,
      });

      // Create new document
      const docRef = doc(this.flowsCollection);
      const now = Timestamp.now();

      const flowData: FlowConfiguration = {
        ...flowConfig,
        id: docRef.id,
        createdAt: now,
        updatedAt: now,
      } as FlowConfiguration;

      await setDoc(docRef, this.flowToFirestore(flowData));

      // Create initial version
      await this.createVersion(flowData, userId, 'Initial version');

      return flowData;
    } catch (error) {
      console.error('Error creating flow:', error);
      if (error instanceof FlowServiceError) {
        throw error;
      }
      throw new FlowServiceError('Failed to create flow', error);
    }
  }

  /**
   * Update flow configuration
   */
  async updateFlow(
    flowId: string,
    updates: Partial<FlowConfiguration>,
    userId: string,
    versionMessage?: string
  ): Promise<FlowConfiguration> {
    try {
      const docRef = doc(this.flowsCollection, flowId);
      const existing = await this.getFlowById(flowId);

      if (!existing) {
        throw new FlowNotFoundError(flowId);
      }

      // Validate updated configuration
      const updatedFlow = { ...existing, ...updates };
      const errors = validateFlowConfiguration(updatedFlow);
      if (errors.length > 0) {
        throw new ValidationError('Flow validation failed', errors);
      }

      // Increment version
      const newVersion = existing.version + 1;

      const updateData = {
        ...updates,
        version: newVersion,
        updatedAt: Timestamp.now(),
      };

      await updateDoc(docRef, this.flowToFirestore(updateData));

      // Create version snapshot
      const updatedFlowConfig = { ...existing, ...updateData };
      await this.createVersion(updatedFlowConfig, userId, versionMessage);

      return updatedFlowConfig;
    } catch (error) {
      console.error('Error updating flow:', error);
      if (error instanceof FlowServiceError) {
        throw error;
      }
      throw new FlowServiceError('Failed to update flow', error);
    }
  }

  /**
   * Update flow status
   */
  async updateFlowStatus(
    flowId: string,
    status: FlowStatus,
    userId: string
  ): Promise<void> {
    try {
      const docRef = doc(this.flowsCollection, flowId);
      const existing = await this.getFlowById(flowId);

      if (!existing) {
        throw new FlowNotFoundError(flowId);
      }

      const updateData: any = {
        status,
        updatedAt: Timestamp.now(),
      };

      if (status === 'active' && !existing.publishedAt) {
        updateData.publishedAt = Timestamp.now();
      }

      await updateDoc(docRef, updateData);

      // Create version snapshot for status change
      await this.createVersion(
        { ...existing, status },
        userId,
        `Status changed to ${status}`
      );
    } catch (error) {
      console.error('Error updating flow status:', error);
      if (error instanceof FlowServiceError) {
        throw error;
      }
      throw new FlowServiceError('Failed to update flow status', error);
    }
  }

  /**
   * Delete flow configuration
   */
  async deleteFlow(flowId: string): Promise<void> {
    try {
      const docRef = doc(this.flowsCollection, flowId);
      const existing = await this.getFlowById(flowId);

      if (!existing) {
        throw new FlowNotFoundError(flowId);
      }

      // Soft delete by setting status to archived
      await this.updateFlowStatus(flowId, 'archived', 'system');

      // Optionally, hard delete if needed
      // await deleteDoc(docRef);
    } catch (error) {
      console.error('Error deleting flow:', error);
      if (error instanceof FlowServiceError) {
        throw error;
      }
      throw new FlowServiceError('Failed to delete flow', error);
    }
  }

  /**
   * Get flow versions
   */
  async getFlowVersions(flowId: string, limitCount = 10): Promise<FlowVersion[]> {
    try {
      const q = query(
        this.versionsCollection,
        where('flowId', '==', flowId),
        orderBy('version', 'desc'),
        limit(limitCount)
      );

      const snapshot = await getDocs(q);

      return snapshot.docs.map(doc => doc.data() as FlowVersion);
    } catch (error) {
      console.error('Error getting flow versions:', error);
      throw new FlowServiceError('Failed to get flow versions', error);
    }
  }

  /**
   * Get specific flow version
   */
  async getFlowVersion(flowId: string, version: number): Promise<FlowVersion | null> {
    try {
      const q = query(
        this.versionsCollection,
        where('flowId', '==', flowId),
        where('version', '==', version),
        limit(1)
      );

      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        return null;
      }

      return snapshot.docs[0].data() as FlowVersion;
    } catch (error) {
      console.error('Error getting flow version:', error);
      throw new FlowServiceError('Failed to get flow version', error);
    }
  }

  /**
   * Restore flow to previous version
   */
  async restoreFlowVersion(
    flowId: string,
    version: number,
    userId: string
  ): Promise<FlowConfiguration> {
    try {
      const versionData = await this.getFlowVersion(flowId, version);

      if (!versionData) {
        throw new FlowVersionNotFoundError(flowId, version);
      }

      // Update flow with version data
      return await this.updateFlow(
        flowId,
        versionData.configuration,
        userId,
        `Restored to version ${version}`
      );
    } catch (error) {
      console.error('Error restoring flow version:', error);
      if (error instanceof FlowServiceError) {
        throw error;
      }
      throw new FlowServiceError('Failed to restore flow version', error);
    }
  }

  /**
   * Create version snapshot
   */
  private async createVersion(
    flowConfig: FlowConfiguration,
    userId: string,
    message?: string
  ): Promise<void> {
    try {
      const versionDoc = doc(this.versionsCollection);

      const versionData: FlowVersion = {
        flowId: flowConfig.id,
        version: flowConfig.version,
        configuration: flowConfig,
        createdBy: userId,
        createdAt: Timestamp.now(),
        message,
        previousVersion: flowConfig.version > 1 ? flowConfig.version - 1 : undefined,
      };

      await setDoc(versionDoc, versionData);
    } catch (error) {
      console.error('Error creating version:', error);
      // Don't throw - version creation failure shouldn't block main operation
    }
  }

  /**
   * Map Firestore document to FlowConfiguration
   */
  private mapToFlowConfiguration(id: string, data: any): FlowConfiguration {
    return {
      id,
      name: data.name,
      displayName: data.displayName,
      description: data.description,
      version: data.version,
      status: data.status,
      category: data.category,
      tags: data.tags || [],
      steps: data.steps || [],
      inputSchema: data.inputSchema || {},
      outputSchema: data.outputSchema || {},
      createdBy: data.createdBy,
      createdAt: data.createdAt,
      updatedAt: data.updatedAt,
      publishedAt: data.publishedAt,
      settings: data.settings,
    };
  }

  /**
   * Convert FlowConfiguration to Firestore format
   */
  private flowToFirestore(flow: Partial<FlowConfiguration>): any {
    const firestoreData: any = {};

    // Only include defined fields
    if (flow.name !== undefined) firestoreData.name = flow.name;
    if (flow.displayName !== undefined) firestoreData.displayName = flow.displayName;
    if (flow.description !== undefined) firestoreData.description = flow.description;
    if (flow.version !== undefined) firestoreData.version = flow.version;
    if (flow.status !== undefined) firestoreData.status = flow.status;
    if (flow.category !== undefined) firestoreData.category = flow.category;
    if (flow.tags !== undefined) firestoreData.tags = flow.tags;
    if (flow.steps !== undefined) firestoreData.steps = flow.steps;
    if (flow.inputSchema !== undefined) firestoreData.inputSchema = flow.inputSchema;
    if (flow.outputSchema !== undefined) firestoreData.outputSchema = flow.outputSchema;
    if (flow.createdBy !== undefined) firestoreData.createdBy = flow.createdBy;
    if (flow.createdAt !== undefined) firestoreData.createdAt = flow.createdAt;
    if (flow.updatedAt !== undefined) firestoreData.updatedAt = flow.updatedAt;
    if (flow.publishedAt !== undefined) firestoreData.publishedAt = flow.publishedAt;
    if (flow.settings !== undefined) firestoreData.settings = flow.settings;

    return firestoreData;
  }
}

/**
 * Flow filters interface
 */
export interface FlowFilters {
  status?: FlowStatus;
  category?: string;
  tags?: string[];
  limit?: number;
}

/**
 * Custom error classes
 */
export class FlowServiceError extends Error {
  public readonly cause?: any;

  constructor(message: string, cause?: any) {
    super(message);
    this.name = 'FlowServiceError';
    this.cause = cause;
  }
}

export class FlowNotFoundError extends FlowServiceError {
  constructor(flowId: string) {
    super(`Flow not found: ${flowId}`);
    this.name = 'FlowNotFoundError';
  }
}

export class FlowAlreadyExistsError extends FlowServiceError {
  constructor(flowName: string) {
    super(`Flow already exists: ${flowName}`);
    this.name = 'FlowAlreadyExistsError';
  }
}

export class FlowVersionNotFoundError extends FlowServiceError {
  constructor(flowId: string, version: number) {
    super(`Flow version not found: ${flowId} v${version}`);
    this.name = 'FlowVersionNotFoundError';
  }
}

export class ValidationError extends FlowServiceError {
  public readonly errors: string[];

  constructor(message: string, errors: string[]) {
    super(message);
    this.name = 'ValidationError';
    this.errors = errors;
  }
}

/**
 * Singleton instance
 */
export const flowConfigService = new FlowConfigService();

/**
 * Convenience functions
 */
export async function getFlowConfiguration(flowName: string): Promise<FlowConfiguration | null> {
  return flowConfigService.getFlowByName(flowName);
}

export async function listAllFlows(filters?: FlowFilters): Promise<FlowConfiguration[]> {
  return flowConfigService.listFlows(filters);
}

export async function createNewFlow(
  flow: Partial<FlowConfiguration>,
  userId: string
): Promise<FlowConfiguration> {
  return flowConfigService.createFlow(flow, userId);
}

export async function updateFlowConfig(
  flowId: string,
  updates: Partial<FlowConfiguration>,
  userId: string,
  message?: string
): Promise<FlowConfiguration> {
  return flowConfigService.updateFlow(flowId, updates, userId, message);
}
