{"file_path": "src/services/tool-registry-service.ts", "initial_content": "/**
 * Tool Registry Service
 * 
 * Manages tool configurations and executions.
 * Handles built-in, custom, and external tools.
 */

import {
  collection,
  doc,
  getDoc,
  getDocs,
  setDoc,
  updateDoc,
  query,
  where,
  orderBy,
  Timestamp,
  QueryConstraint,
} from 'firebase/firestore';
import { db } from '@/lib/firebase/client-init';
import {
  ToolConfiguration,
  ToolType,
  ToolStatus,
  BuiltinToolMetadata,
  ExternalToolConfig,
  TOOL_COLLECTIONS,
  TOOL_CATEGORIES,
  validateToolConfiguration,
  createToolConfiguration,
  ToolNotFoundError as ModelToolNotFoundError,
  ToolExecutionError as ModelToolExecutionError,
  ToolTimeoutError as ModelToolTimeoutError,
} from '@/lib/models/tool-config';

/**
 * Tool Registry Service Class
 */
export class ToolRegistryService {
  private readonly toolsCollection = collection(db, TOOL_COLLECTIONS.CONFIGURATIONS);
  private builtinTools: Map<string, BuiltinToolMetadata> = new Map();

  /**
   * Register a built-in tool
   */
  registerBuiltin(metadata: BuiltinToolMetadata): void {
    this.builtinTools.set(metadata.name, metadata);
    console.log(`Registered built-in tool: ${metadata.name}`);
  }

  /**
   * Get tool by name
   */
  async getToolByName(toolName: string): Promise<ToolConfiguration | null> {
    try {
      // Check built-in tools first
      const builtin = this.builtinTools.get(toolName);
      if (builtin) {
        return this.builtinToConfiguration(builtin);
      }

      // Query Firestore for custom/external tools
      const q = query(
        this.toolsCollection,
        where('name', '==', toolName),
        where('status', '==', 'active')
      );

      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        return null;
      }

      return snapshot.docs[0].data() as ToolConfiguration;
    } catch (error) {
      console.error('Error getting tool by name:', error);
      throw new ToolServiceError('Failed to get tool by name', error);
    }
  }

  /**
   * List all available tools
   */
  async listTools(filters?: ToolFilters): Promise<ToolConfiguration[]> {
    try {
      const tools: ToolConfiguration[] = [];

      // Add built-in tools
      if (!filters?.type || filters.type === 'builtin') {
        for (const builtin of this.builtinTools.values()) {
          const config = this.builtinToConfiguration(builtin);

          // Apply filters
          if (filters?.category && config.category !== filters.category) {
            continue;
          }

          if (filters?.tags && !filters.tags.some(tag => config.tags.includes(tag))) {
            continue;
          }

          tools.push(config);
        }
      }

      // Query Firestore for custom/external tools
      if (!filters?.type || filters.type !== 'builtin') {
        const constraints: QueryConstraint[] = [];

        if (filters?.type) {
          constraints.push(where('type', '==', filters.type));
        }

        if (filters?.category) {
          constraints.push(where('category', '==', filters.category));
        }

        if (filters?.status) {
          constraints.push(where('status', '==', filters.status));
        }

        if (filters?.tags && filters.tags.length > 0) {
          constraints.push(where('tags', 'array-contains-any', filters.tags));
        }

        constraints.push(orderBy('createdAt', 'desc'));

        const q = query(this.toolsCollection, ...constraints);
        const snapshot = await getDocs(q);

        tools.push(...snapshot.docs.map(doc => doc.data() as ToolConfiguration));
      }

      return tools;
    } catch (error) {
      console.error('Error listing tools:', error);
      throw new ToolServiceError('Failed to list tools', error);
    }
  }

  /**
   * Register a custom or external tool
   */
  async registerTool(
    tool: Partial<ToolConfiguration>,
    userId: string
  ): Promise<ToolConfiguration> {
    try {
      // Validate tool configuration
      const errors = validateToolConfiguration(tool);
      if (errors.length > 0) {
        throw new ValidationError('Tool validation failed', errors);
      }

      // Check if tool with same name already exists
      const existing = await this.getToolByName(tool.name!);
      if (existing) {
        throw new ToolAlreadyExistsError(tool.name!);
      }

      // Create tool configuration with defaults
      const toolConfig = createToolConfiguration({
        ...tool,
        createdBy: userId,
      });

      // Create new document
      const docRef = doc(this.toolsCollection);
      const now = Timestamp.now();

      const toolData: ToolConfiguration = {
        ...toolConfig,
        createdAt: now,
        updatedAt: now,
      };

      await setDoc(docRef, toolData);

      return toolData;
    } catch (error) {
      console.error('Error registering tool:', error);
      if (error instanceof ToolServiceError) {
        throw error;
      }
      throw new ToolServiceError('Failed to register tool', error);
    }
  }

  /**
   * Update tool configuration
   */
  async updateTool(
    toolName: string,
    updates: Partial<ToolConfiguration>,
    userId: string
  ): Promise<ToolConfiguration> {
    try {
      // Cannot update built-in tools
      if (this.builtinTools.has(toolName)) {
        throw new ToolServiceError('Cannot update built-in tool');
      }

      const existing = await this.getToolByName(toolName);

      if (!existing) {
        throw new ToolNotFoundError(toolName);
      }

      // Validate updated configuration
      const updatedTool = { ...existing, ...updates };
      const errors = validateToolConfiguration(updatedTool);
      if (errors.length > 0) {
        throw new ValidationError('Tool validation failed', errors);
      }

      // Find document by name
      const q = query(this.toolsCollection, where('name', '==', toolName));
      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        throw new ToolNotFoundError(toolName);
      }

      const docRef = doc(this.toolsCollection, snapshot.docs[0].id);

      await updateDoc(docRef, {
        ...updates,
        updatedAt: Timestamp.now(),
      });

      return { ...existing, ...updates, updatedAt: Timestamp.now() };
    } catch (error) {
      console.error('Error updating tool:', error);
      if (error instanceof ToolServiceError) {
        throw error;
      }
      throw new ToolServiceError('Failed to update tool', error);
    }
  }

  /**
   * Execute a tool
   */
  async executeTool(
    toolName: string,
    parameters: Record<string, any>,
    timeoutMs?: number
  ): Promise<any> {
    try {
      const tool = await this.getToolByName(toolName);

      if (!tool) {
        throw new ToolNotFoundError(toolName);
      }

      if (tool.status !== 'active') {
        throw new ToolServiceError(`Tool is not active: ${toolName} (status: ${tool.status})`);
      }

      const timeout = timeoutMs || tool.timeout || 30000;

      // Execute based on tool type
      switch (tool.type) {
        case 'builtin':
          return await this.executeBuiltinTool(toolName, parameters, timeout);

        case 'custom':
          return await this.executeCustomTool(tool, parameters, timeout);

        case 'external':
          return await this.executeExternalTool(tool, parameters, timeout);

        default:
          throw new ToolServiceError(`Unknown tool type: ${tool.type}`);
      }
    } catch (error) {
      console.error('Error executing tool:', error);
      if (error instanceof ToolServiceError) {
        throw error;
      }
      throw new ModelToolExecutionError(toolName, 'Tool execution failed', error as Error);
    }
  }

  /**
   * Execute built-in tool
   */
  private async executeBuiltinTool(
    toolName: string,
    parameters: Record<string, any>,
    timeout: number
  ): Promise<any> {
    const metadata = this.builtinTools.get(toolName);

    if (!metadata) {
      throw new ToolNotFoundError(toolName);
    }

    // Execute with timeout
    return await this.withTimeout(
      metadata.handler(parameters),
      timeout,
      toolName
    );
  }

  /**
   * Execute custom tool
   */
  private async executeCustomTool(
    tool: ToolConfiguration,
    parameters: Record<string, any>,
    timeout: number
  ): Promise<any> {
    // For custom tools, the handler is a function name that should be imported
    // This is a placeholder - implement dynamic import based on your needs
    throw new ToolServiceError('Custom tool execution not yet implemented');
  }

  /**
   * Execute external tool (HTTP API)
   */
  private async executeExternalTool(
    tool: ToolConfiguration,
    parameters: Record<string, any>,
    timeout: number
  ): Promise<any> {
    try {
      const url = tool.handler;

      // Parse as ExternalToolConfig if available
      const externalConfig: ExternalToolConfig = {
        name: tool.name,
        endpoint: url,
        method: 'POST', // Default to POST
        authType: 'none',
      };

      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        ...externalConfig.headers,
      };

      // Add authentication if configured
      if (externalConfig.authType === 'bearer' && externalConfig.authConfig?.token) {
        headers['Authorization'] = `Bearer ${externalConfig.authConfig.token}`;
      } else if (externalConfig.authType === 'api-key' && externalConfig.authConfig?.apiKey) {
        headers['X-API-Key'] = externalConfig.authConfig.apiKey;
      }

      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeout);

      const response = await fetch(url, {
        method: externalConfig.method,
        headers,
        body: JSON.stringify(parameters),
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new ToolServiceError(`External tool returned ${response.status}: ${response.statusText}`);
      }

      const result = await response.json();

      // Extract result based on response mapping if configured
      return result;
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        throw new ModelToolTimeoutError(tool.name, timeout);
      }
      throw error;
    }
  }

  /**
   * Execute promise with timeout
   */
  private async withTimeout<T>(
    promise: Promise<T>,
    timeout: number,
    toolName: string
  ): Promise<T> {
    return Promise.race([
      promise,
      new Promise<T>((_, reject) =>
        setTimeout(() => reject(new ModelToolTimeoutError(toolName, timeout)), timeout)
      ),
    ]);
  }

  /**
   * Convert built-in metadata to configuration
   */
  private builtinToConfiguration(metadata: BuiltinToolMetadata): ToolConfiguration {
    return {
      name: metadata.name,
      displayName: metadata.displayName,
      description: metadata.description,
      category: metadata.category,
      tags: [],
      type: 'builtin',
      handler: metadata.name,
      inputSchema: metadata.inputSchema,
      outputSchema: metadata.outputSchema,
      status: 'active',
      version: '1.0.0',
      createdBy: 'system',
      createdAt: Timestamp.now(),
      updatedAt: Timestamp.now(),
      examples: metadata.examples,
    };
  }

  /**
   * Get tool documentation
   */
  async getToolDocumentation(toolName: string): Promise<string> {
    const tool = await this.getToolByName(toolName);

    if (!tool) {
      throw new ToolNotFoundError(toolName);
    }

    let doc = `# ${tool.displayName}\n\n`;
    doc += `${tool.description}\n\n`;
    doc += `**Category:** ${tool.category}\n`;
    doc += `**Type:** ${tool.type}\n\n`;

    doc += `## Input Schema\n\`\`\`json\n${JSON.stringify(tool.inputSchema, null, 2)}\n\`\`\`\n\n`;
    doc += `## Output Schema\n\`\`\`json\n${JSON.stringify(tool.outputSchema, null, 2)}\n\`\`\`\n\n`;

    if (tool.examples && tool.examples.length > 0) {
      doc += `## Examples\n\n`;
      tool.examples.forEach((example, i) => {
        doc += `### ${i + 1}. ${example.name}\n\n`;
        doc += `**Input:**\n\`\`\`json\n${JSON.stringify(example.input, null, 2)}\n\`\`\`\n\n`;
        doc += `**Output:**\n\`\`\`json\n${JSON.stringify(example.expectedOutput, null, 2)}\n\`\`\`\n\n`;
      });
    }

    if (tool.documentation) {
      doc += `## Additional Documentation\n\n${tool.documentation}\n`;
    }

    return doc;
  }
}

/**
 * Interfaces
 */
export interface ToolFilters {
  type?: ToolType;
  category?: string;
  status?: ToolStatus;
  tags?: string[];
}

/**
 * Custom error classes
 */
export class ToolServiceError extends Error {
  public readonly cause?: any;

  constructor(message: string, cause?: any) {
    super(message);
    this.name = 'ToolServiceError';
    this.cause = cause;
  }
}

export class ToolNotFoundError extends ToolServiceError {
  constructor(toolName: string) {
    super(`Tool not found: ${toolName}`);
    this.name = 'ToolNotFoundError';
  }
}

export class ToolAlreadyExistsError extends ToolServiceError {
  constructor(toolName: string) {
    super(`Tool already exists: ${toolName}`);
    this.name = 'ToolAlreadyExistsError';
  }
}

export class ValidationError extends ToolServiceError {
  public readonly errors: string[];

  constructor(message: string, errors: string[]) {
    super(message);
    this.name = 'ValidationError';
    this.errors = errors;
  }
}

/**
 * Singleton instance
 */
export const toolRegistryService = new ToolRegistryService();

/**
 * Convenience functions
 */
export async function getToolByName(toolName: string): Promise<ToolConfiguration | null> {
  return toolRegistryService.getToolByName(toolName);
}

export async function listAvailableTools(filters?: ToolFilters): Promise<ToolConfiguration[]> {
  return toolRegistryService.listTools(filters);
}

export async function executeTool(
  toolName: string,
  parameters: Record<string, any>,
  timeout?: number
): Promise<any> {
  return toolRegistryService.executeTool(toolName, parameters, timeout);
}

export function registerBuiltinTool(metadata: BuiltinToolMetadata): void {
  toolRegistryService.registerBuiltin(metadata);
}
"}

{"file_path": "src/services/execution-trace-service.ts", "initial_content": "/**
 * Execution Trace Service
 * 
 * Manages execution traces for debugging and monitoring.
 * Stores and retrieves flow execution history.
 */

import {
  collection,
  doc,
  getDoc,
  getDocs,
  setDoc,
  query,
  where,
  orderBy,
  limit,
  Timestamp,
  QueryConstraint,
} from 'firebase/firestore';
import { db } from '@/lib/firebase/client-init';
import {
  ExecutionTrace,
  ExecutionStatus,
  ExecutionSummary,
  ExecutionFilters,
  ExecutionAnalytics,
  TRACE_COLLECTIONS,
  getExecutionSummary,
  formatExecutionTrace,
} from '@/lib/models/execution-trace';

/**
 * Execution Trace Service Class
 */
export class ExecutionTraceService {
  private readonly tracesCollection = collection(db, TRACE_COLLECTIONS.EXECUTIONS);
  private readonly analyticsCollection = collection(db, TRACE_COLLECTIONS.ANALYTICS);

  /**
   * Save execution trace
   */
  async saveTrace(trace: ExecutionTrace): Promise<void> {
    try {
      const docRef = doc(this.tracesCollection, trace.id);
      await setDoc(docRef, this.traceToFirestore(trace));
    } catch (error) {
      console.error('Error saving execution trace:', error);
      throw new TraceServiceError('Failed to save execution trace', error);
    }
  }

  /**
   * Get execution trace by ID
   */
  async getTraceById(traceId: string): Promise<ExecutionTrace | null> {
    try {
      const docRef = doc(this.tracesCollection, traceId);
      const docSnap = await getDoc(docRef);

      if (!docSnap.exists()) {
        return null;
      }

      return this.mapToExecutionTrace(docSnap.data());
    } catch (error) {
      console.error('Error getting execution trace:', error);
      throw new TraceServiceError('Failed to get execution trace', error);
    }
  }

  /**
   * List execution traces with filters
   */
  async listTraces(filters?: ExecutionFilters): Promise<ExecutionSummary[]> {
    try {
      const constraints: QueryConstraint[] = [];

      if (filters?.flowId) {
        constraints.push(where('flowId', '==', filters.flowId));
      }

      if (filters?.flowName) {
        constraints.push(where('flowName', '==', filters.flowName));
      }

      if (filters?.status) {
        constraints.push(where('status', '==', filters.status));
      }

      if (filters?.userId) {
        constraints.push(where('userId', '==', filters.userId));
      }

      if (filters?.startDate) {
        constraints.push(where('startTime', '>=', Timestamp.fromDate(filters.startDate)));
      }

      if (filters?.endDate) {
        constraints.push(where('startTime', '<=', Timestamp.fromDate(filters.endDate)));
      }

      if (filters?.hasError !== undefined) {
        if (filters.hasError) {
          constraints.push(where('status', '==', 'failed'));
        } else {
          constraints.push(where('status', '==', 'completed'));
        }
      }

      // Order by start time (most recent first)
      constraints.push(orderBy('startTime', 'desc'));

      // Limit results
      const limitCount = filters?.maxDuration ? 1000 : 50; // Get more if filtering by duration
      constraints.push(limit(limitCount));

      const q = query(this.tracesCollection, ...constraints);
      const snapshot = await getDocs(q);

      let traces = snapshot.docs.map(doc => {
        const data = doc.data();
        return getExecutionSummary(this.mapToExecutionTrace(data));
      });

      // Post-filter for duration (can't do in Firestore query)
      if (filters?.minDuration !== undefined) {
        traces = traces.filter(t => (t.duration || 0) >= filters.minDuration!);
      }

      if (filters?.maxDuration !== undefined) {
        traces = traces.filter(t => (t.duration || 0) <= filters.maxDuration!);
      }

      return traces;
    } catch (error) {
      console.error('Error listing execution traces:', error);
      throw new TraceServiceError('Failed to list execution traces', error);
    }
  }

  /**
   * Get traces for a specific flow
   */
  async getFlowTraces(
    flowId: string,
    limitCount = 20
  ): Promise<ExecutionSummary[]> {
    return this.listTraces({ flowId, limit: limitCount });
  }

  /**
   * Get traces for a specific user
   */
  async getUserTraces(
    userId: string,
    limitCount = 20
  ): Promise<ExecutionSummary[]> {
    return this.listTraces({ userId, limit: limitCount });
  }

  /**
   * Get failed executions
   */
  async getFailedExecutions(limitCount = 50): Promise<ExecutionSummary[]> {
    return this.listTraces({ status: 'failed', limit: limitCount });
  }

  /**
   * Get slow executions
   */
  async getSlowExecutions(
    minDuration: number,
    limitCount = 50
  ): Promise<ExecutionSummary[]> {
    return this.listTraces({ minDuration, limit: limitCount });
  }

  /**
   * Get execution analytics for a flow
   */
  async getFlowAnalytics(
    flowId: string,
    period: 'hour' | 'day' | 'week' | 'month' = 'day'
  ): Promise<ExecutionAnalytics | null> {
    try {
      const q = query(
        this.analyticsCollection,
        where('flowId', '==', flowId),
        where('period', '==', period),
        orderBy('startDate', 'desc'),
        limit(1)
      );

      const snapshot = await getDocs(q);

      if (snapshot.empty) {
        // Calculate analytics on the fly
        return await this.calculateAnalytics(flowId, period);
      }

      return snapshot.docs[0].data() as ExecutionAnalytics;
    } catch (error) {
      console.error('Error getting flow analytics:', error);
      throw new TraceServiceError('Failed to get flow analytics', error);
    }
  }

  /**
   * Calculate analytics from traces
   */
  private async calculateAnalytics(
    flowId: string,
    period: 'hour' | 'day' | 'week' | 'month'
  ): Promise<ExecutionAnalytics> {
    // Calculate date range based on period
    const endDate = new Date();
    const startDate = new Date();

    switch (period) {
      case 'hour':
        startDate.setHours(startDate.getHours() - 1);
        break;
      case 'day':
        startDate.setDate(startDate.getDate() - 1);
        break;
      case 'week':
        startDate.setDate(startDate.getDate() - 7);
        break;
      case 'month':
        startDate.setMonth(startDate.getMonth() - 1);
        break;
    }

    // Get all traces in period
    const traces = await this.listTraces({
      flowId,
      startDate,
      endDate,
    });

    // Calculate metrics
    const totalExecutions = traces.length;
    const successfulExecutions = traces.filter(t => t.status === 'completed').length;
    const failedExecutions = traces.filter(t => t.status === 'failed').length;
    const cancelledExecutions = traces.filter(t => t.status === 'cancelled').length;

    const durations = traces
      .filter(t => t.duration !== undefined)
      .map(t => t.duration!);

    const averageDuration = durations.length > 0
      ? durations.reduce((sum, d) => sum + d, 0) / durations.length
      : 0;

    const sortedDurations = [...durations].sort((a, b) => a - b);
    const medianDuration = sortedDurations.length > 0
      ? sortedDurations[Math.floor(sortedDurations.length / 2)]
      : 0;

    const p95Duration = sortedDurations.length > 0
      ? sortedDurations[Math.floor(sortedDurations.length * 0.95)]
      : 0;

    const p99Duration = sortedDurations.length > 0
      ? sortedDurations[Math.floor(sortedDurations.length * 0.99)]
      : 0;

    const successRate = totalExecutions > 0
      ? successfulExecutions / totalExecutions
      : 0;

    return {
      flowId,
      period,
      startDate: Timestamp.fromDate(startDate),
      endDate: Timestamp.fromDate(endDate),
      totalExecutions,
      successfulExecutions,
      failedExecutions,
      cancelledExecutions,
      averageDuration,
      medianDuration,
      p95Duration,
      p99Duration,
      successRate,
    };
  }

  /**
   * Save analytics to database
   */
  async saveAnalytics(analytics: ExecutionAnalytics): Promise<void> {
    try {
      const docRef = doc(this.analyticsCollection);
      await setDoc(docRef, analytics);
    } catch (error) {
      console.error('Error saving analytics:', error);
      // Don't throw - analytics save failure shouldn't block
    }
  }

  /**
   * Delete old traces (cleanup)
   */
  async deleteOldTraces(daysToKeep = 30): Promise<number> {
    try {
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - daysToKeep);

      const q = query(
        this.tracesCollection,
        where('startTime', '<', Timestamp.fromDate(cutoffDate)),
        limit(500) // Delete in batches
      );

      const snapshot = await getDocs(q);
      let deletedCount = 0;

      // Note: In production, use batch operations or Cloud Functions
      for (const document of snapshot.docs) {
        await document.ref.delete();
        deletedCount++;
      }

      return deletedCount;
    } catch (error) {
      console.error('Error deleting old traces:', error);
      throw new TraceServiceError('Failed to delete old traces', error);
    }
  }

  /**
   * Format trace for display
   */
  formatTrace(trace: ExecutionTrace): string {
    return formatExecutionTrace(trace);
  }

  /**
   * Map Firestore document to ExecutionTrace
   */
  private mapToExecutionTrace(data: any): ExecutionTrace {
    return {
      id: data.id,
      flowId: data.flowId,
      flowName: data.flowName,
      flowVersion: data.flowVersion,
      startTime: data.startTime,
      endTime: data.endTime,
      duration: data.duration,
      status: data.status,
      input: data.input,
      output: data.output,
      error: data.error,
      stepTraces: data.stepTraces || [],
      userId: data.userId,
      requestId: data.requestId,
      environment: data.environment,
      metrics: data.metrics,
    };
  }

  /**
   * Convert ExecutionTrace to Firestore format
   */
  private traceToFirestore(trace: ExecutionTrace): any {
    return {
      id: trace.id,
      flowId: trace.flowId,
      flowName: trace.flowName,
      flowVersion: trace.flowVersion,
      startTime: trace.startTime,
      endTime: trace.endTime,
      duration: trace.duration,
      status: trace.status,
      input: trace.input,
      output: trace.output,
      error: trace.error,
      stepTraces: trace.stepTraces,
      userId: trace.userId,
      requestId: trace.requestId,
      environment: trace.environment,
      metrics: trace.metrics,
    };
  }
}

/**
 * Custom error class
 */
export class TraceServiceError extends Error {
  public readonly cause?: any;

  constructor(message: string, cause?: any) {
    super(message);
    this.name = 'TraceServiceError';
    this.cause = cause;
  }
}

/**
 * Singleton instance
 */
export const executionTraceService = new ExecutionTraceService();

/**
 * Convenience functions
 */
export async function saveExecutionTrace(trace: ExecutionTrace): Promise<void> {
  return executionTraceService.saveTrace(trace);
}

export async function getExecutionTrace(traceId: string): Promise<ExecutionTrace | null> {
  return executionTraceService.getTraceById(traceId);
}

export async function listExecutionTraces(filters?: ExecutionFilters): Promise<ExecutionSummary[]> {
  return executionTraceService.listTraces(filters);
}

export async function getFlowExecutionAnalytics(
  flowId: string,
  period?: 'hour' | 'day' | 'week' | 'month'
): Promise<ExecutionAnalytics | null> {
  return executionTraceService.getFlowAnalytics(flowId, period);
}
"}

