{"file_path": "src/app/api/admin/analytics/route.ts", "initial_content": "/**
 * Analytics API
 * 
 * GET /api/admin/analytics - Get execution analytics for flows
 */

import { NextRequest, NextResponse } from 'next/server';
import { executionTraceService } from '@/services/execution-trace-service';

/**
 * GET /api/admin/analytics
 * Get execution analytics for a specific flow
 */
export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const flowId = searchParams.get('flowId');
    const period = searchParams.get('period') as 'hour' | 'day' | 'week' | 'month' | null;

    if (!flowId) {
      return NextResponse.json(
        {
          success: false,
          error: 'Flow ID is required',
        },
        { status: 400 }
      );
    }

    const analytics = await executionTraceService.getFlowAnalytics(
      flowId,
      period || 'day'
    );

    if (!analytics) {
      return NextResponse.json(
        {
          success: false,
          error: 'No analytics data available',
        },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      analytics,
    });
  } catch (error) {
    console.error('Error getting analytics:', error);
    return NextResponse.json(
      {
        success: false,
        error: error instanceof Error ? error.message : 'Failed to get analytics',
      },
      { status: 500 }
    );
  }
}
"}

{"file_path": "src/components/admin/flow-builder/FlowBuilderInterface.tsx", "initial_content": "/**
 * Flow Builder Interface
 * 
 * Visual interface for creating and editing flows with drag-and-drop functionality.
 */

'use client';

import React, { useState } from 'react';
import { FlowConfiguration, FlowStep, StepType } from '@/lib/models/flow-config';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Plus, Save, Play, Settings, Trash2, MoveUp, MoveDown } from 'lucide-react';

interface FlowBuilderInterfaceProps {
  initialFlow?: FlowConfiguration;
  onSave?: (flow: Partial<FlowConfiguration>) => void;
  onTest?: (flow: Partial<FlowConfiguration>) => void;
}

export function FlowBuilderInterface({
  initialFlow,
  onSave,
  onTest,
}: FlowBuilderInterfaceProps) {
  const [flow, setFlow] = useState<Partial<FlowConfiguration>>(
    initialFlow || {
      name: '',
      displayName: '',
      description: '',
      category: 'general',
      tags: [],
      steps: [],
      status: 'draft',
    }
  );

  const [selectedStepIndex, setSelectedStepIndex] = useState<number | null>(null);

  // Step type options
  const stepTypes: { value: StepType; label: string; description: string }[] = [
    { value: 'GENERATE', label: 'Generate', description: 'Generate text with LLM' },
    { value: 'RETRIEVE', label: 'Retrieve', description: 'Retrieve context from RAG' },
    { value: 'TOOL', label: 'Tool', description: 'Execute a tool' },
    { value: 'FORMAT', label: 'Format', description: 'Format output' },
    { value: 'CONDITION', label: 'Condition', description: 'Conditional branching' },
    { value: 'LOOP', label: 'Loop', description: 'Iterative processing' },
  ];

  // Add new step
  const handleAddStep = (type: StepType) => {
    const newStep: FlowStep = {
      id: `step-${Date.now()}`,
      type,
      name: `${type} Step`,
      description: '',
      config: { type } as any,
      inputSchema: {},
      outputSchema: {},
    };

    setFlow({
      ...flow,
      steps: [...(flow.steps || []), newStep],
    });

    setSelectedStepIndex((flow.steps || []).length);
  };

  // Update step
  const handleUpdateStep = (index: number, updates: Partial<FlowStep>) => {
    const updatedSteps = [...(flow.steps || [])];
    updatedSteps[index] = { ...updatedSteps[index], ...updates };
    setFlow({ ...flow, steps: updatedSteps });
  };

  // Delete step
  const handleDeleteStep = (index: number) => {
    const updatedSteps = (flow.steps || []).filter((_, i) => i !== index);
    setFlow({ ...flow, steps: updatedSteps });
    setSelectedStepIndex(null);
  };

  // Move step
  const handleMoveStep = (index: number, direction: 'up' | 'down') => {
    const updatedSteps = [...(flow.steps || [])];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;

    if (targetIndex < 0 || targetIndex >= updatedSteps.length) return;

    [updatedSteps[index], updatedSteps[targetIndex]] = [
      updatedSteps[targetIndex],
      updatedSteps[index],
    ];

    setFlow({ ...flow, steps: updatedSteps });
    setSelectedStepIndex(targetIndex);
  };

  // Save flow
  const handleSave = () => {
    if (onSave) {
      onSave(flow);
    }
  };

  // Test flow
  const handleTest = () => {
    if (onTest) {
      onTest(flow);
    }
  };

  return (
    <div className="flex h-screen bg-gray-50 dark:bg-gray-900">
      {/* Left Sidebar - Step Library */}
      <div className="w-64 border-r bg-white dark:bg-gray-800 p-4">
        <h3 className="font-semibold mb-4 flex items-center gap-2">
          <Plus className="h-4 w-4" />
          Add Steps
        </h3>
        <ScrollArea className="h-[calc(100vh-8rem)]">
          <div className="space-y-2">
            {stepTypes.map((stepType) => (
              <Card
                key={stepType.value}
                className="cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                onClick={() => handleAddStep(stepType.value)}
              >
                <CardContent className="p-3">
                  <div className="font-medium text-sm">{stepType.label}</div>
                  <div className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    {stepType.description}
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </ScrollArea>
      </div>

      {/* Main Canvas */}
      <div className="flex-1 p-6 overflow-auto">
        {/* Flow Header */}
        <Card className="mb-6">
          <CardHeader>
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <Input
                  placeholder="Flow Name"
                  value={flow.displayName || ''}
                  onChange={(e) => setFlow({ ...flow, displayName: e.target.value })}
                  className="text-2xl font-bold border-0 px-0 focus-visible:ring-0"
                />
              </div>
              <div className="flex gap-2">
                <Button variant="outline" onClick={handleTest}>
                  <Play className="h-4 w-4 mr-2" />
                  Test
                </Button>
                <Button onClick={handleSave}>
                  <Save className="h-4 w-4 mr-2" />
                  Save
                </Button>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4">
              <div>
                <Label>Description</Label>
                <Textarea
                  placeholder="Describe what this flow does..."
                  value={flow.description || ''}
                  onChange={(e) => setFlow({ ...flow, description: e.target.value })}
                  rows={2}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label>Internal Name</Label>
                  <Input
                    placeholder="flow-name"
                    value={flow.name || ''}
                    onChange={(e) => setFlow({ ...flow, name: e.target.value })}
                  />
                </div>
                <div>
                  <Label>Category</Label>
                  <Input
                    placeholder="general"
                    value={flow.category || ''}
                    onChange={(e) => setFlow({ ...flow, category: e.target.value })}
                  />
                </div>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Flow Steps */}
        <div className="space-y-4">
          <h3 className="font-semibold text-lg">Flow Steps ({flow.steps?.length || 0})</h3>

          {(!flow.steps || flow.steps.length === 0) && (
            <Card className="border-dashed">
              <CardContent className="flex items-center justify-center h-32 text-gray-500">
                <div className="text-center">
                  <p>No steps added yet</p>
                  <p className="text-sm mt-2">Select a step type from the left sidebar to get started</p>
                </div>
              </CardContent>
            </Card>
          )}

          {flow.steps?.map((step, index) => (
            <Card
              key={step.id}
              className={`cursor-pointer transition-all ${
                selectedStepIndex === index
                  ? 'ring-2 ring-primary'
                  : 'hover:bg-gray-50 dark:hover:bg-gray-800'
              }`}
              onClick={() => setSelectedStepIndex(index)}
            >
              <CardHeader>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <Badge variant="outline">{step.type}</Badge>
                    <CardTitle className="text-lg">{step.name}</CardTitle>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleMoveStep(index, 'up');
                      }}
                      disabled={index === 0}
                    >
                      <MoveUp className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleMoveStep(index, 'down');
                      }}
                      disabled={index === (flow.steps?.length || 0) - 1}
                    >
                      <MoveDown className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDeleteStep(index);
                      }}
                    >
                      <Trash2 className="h-4 w-4 text-red-500" />
                    </Button>
                  </div>
                </div>
                {step.description && (
                  <CardDescription>{step.description}</CardDescription>
                )}
              </CardHeader>
            </Card>
          ))}
        </div>
      </div>

      {/* Right Sidebar - Step Editor */}
      {selectedStepIndex !== null && flow.steps && flow.steps[selectedStepIndex] && (
        <div className="w-96 border-l bg-white dark:bg-gray-800 p-4">
          <div className="flex items-center justify-between mb-4">
            <h3 className="font-semibold flex items-center gap-2">
              <Settings className="h-4 w-4" />
              Step Configuration
            </h3>
          </div>
          <ScrollArea className="h-[calc(100vh-8rem)]">
            <div className="space-y-4">
              <div>
                <Label>Step Name</Label>
                <Input
                  value={flow.steps[selectedStepIndex].name}
                  onChange={(e) =>
                    handleUpdateStep(selectedStepIndex, { name: e.target.value })
                  }
                />
              </div>
              <div>
                <Label>Description</Label>
                <Textarea
                  value={flow.steps[selectedStepIndex].description || ''}
                  onChange={(e) =>
                    handleUpdateStep(selectedStepIndex, { description: e.target.value })
                  }
                  rows={3}
                />
              </div>
              <div>
                <Label>Step Type</Label>
                <Select
                  value={flow.steps[selectedStepIndex].type}
                  onValueChange={(value) =>
                    handleUpdateStep(selectedStepIndex, { type: value as StepType })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {stepTypes.map((type) => (
                      <SelectItem key={type.value} value={type.value}>
                        {type.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="pt-4 border-t">
                <p className="text-sm text-gray-500 mb-2">
                  Additional configuration for {flow.steps[selectedStepIndex].type} step will be added here.
                </p>
              </div>
            </div>
          </ScrollArea>
        </div>
      )}
    </div>
  );
}
"}

{"file_path": "src/components/admin/prompts/PromptEditor.tsx", "initial_content": "/**
 * Prompt Editor
 * 
 * Rich editor for creating and managing prompt templates with variables.
